window.REVISION_SUBJECTS=window.REVISION_SUBJECTS||[];
window.REVISION_SUBJECTS.push({"config":{"brandIcon":"✝️","brandSubtitle":"AQA GCSE Religious Studies A (8062)","brandTitle":"Christianity (AQA RS A)","breadcrumb":"Religious Studies / AQA A / Christianity","examBoard":"AQA GCSE","footerNote":"Original practice questions written to the AQA GCSE Religious Studies A (8062) specification, using the question structure for exams from June 2026 (1, 1, 4, 6, 12 marks). Not past-paper material. Model answers are indicative exemplars, not official AQA mark schemes; other valid answers are credited in the exam.","heroEyebrow":"Component 1 · Christianity · Beliefs \u0026 teachings · Practices","pageTitle":"AQA GCSE Religious Studies A — Christianity Revision","papers":[{"id":"Beliefs","label":"Beliefs \u0026 teachings","subtitle":"Key beliefs · Jesus Christ and salvation (1.1–1.9)","title":"Beliefs and teachings"},{"id":"Practices","label":"Practices","subtitle":"Worship and festivals · The role of the church in the local and worldwide community (2.1–2.10)","title":"Practices"}],"storageId":"aqa_rs_a_christianity","subjectArea":"Religious Studies","subjectName":"Christianity"},"questions":{"paper1":[{"id":"aqa-rs-a-christianity-paper1-1-1-0","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Which one of the following words means that God is all-powerful?\nA  Omniscient\nB  Omnipotent\nC  Omnipresent\nD  Benevolent","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Omnipotent\n\nOmnipotent comes from the Latin omnis (all) and potens (powerful). Omniscient means all-knowing, omnipresent means present everywhere, and benevolent means all-loving/good. Christians see God's omnipotence in creation ('Let there be light', Genesis 1:3) and in Jesus' words 'with God all things are possible' (Matthew 19:26).","evidence":["Matthew 19:26","Genesis 1:3"],"examTip":"Learn the four 'omni'/quality words precisely — they are a favourite multiple-choice target.","answerTopic":"omnipotence"},{"id":"aqa-rs-a-christianity-paper1-1-1-1","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Which one of the following is the problem of evil and suffering most directly a challenge to?\nA  Belief that God is the Trinity\nB  Belief that God is omnipotent and loving\nC  Belief in the incarnation\nD  Belief in the authority of the Church","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Belief that God is omnipotent and loving\n\nThe problem of evil asks why a God who is all-powerful (able to stop suffering) and all-loving (wanting to stop suffering) allows evil to exist. It is therefore a direct challenge to belief that God is omnipotent and loving (and just). The other options are not the focus of the problem.","evidence":["Epicurus' (attributed) dilemma","1 John 4:8 'God is love'"],"examTip":"Link the problem of evil to the specific qualities it challenges: omnipotent, loving (benevolent) and just.","answerTopic":"problem of evil"},{"id":"aqa-rs-a-christianity-paper1-1-1-2","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Give one way in which the Bible shows that God is just.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• God judges people fairly according to what they have done (e.g. the parable of the sheep and the goats, Matthew 25:31–46).\n• God commands justice for the poor and oppressed ('let justice roll on like a river', Amos 5:24).\n• God punishes wrongdoing but is also merciful (e.g. Adam and Eve are punished for disobedience in Genesis 3).\n• God's laws (e.g. the Ten Commandments) set out what is right and fair.","evidence":["Amos 5:24","Matthew 25:31–46","Genesis 3"],"examTip":"One accurate point is enough — don't waste time writing more for a 1-mark question.","answerTopic":"justice of God"},{"id":"aqa-rs-a-christianity-paper1-1-1-3","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Give one type of evil that causes suffering.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Either:\n• Moral evil — suffering caused by humans misusing free will (e.g. murder, war, theft).\n• Natural evil — suffering caused by natural events not directly caused by humans (e.g. earthquakes, disease, tsunamis).","evidence":["Moral evil","Natural evil"],"examTip":"Name the type; a quick example is fine but not required.","answerTopic":"types of evil"},{"id":"aqa-rs-a-christianity-paper1-1-1-4","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Explain two ways in which belief that God is loving influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Christians believe 'God is love' (1 John 4:8), they try to show the same unconditional love (agape) to others. This influences them to treat everyone — including enemies and strangers — with kindness and respect, for example by volunteering at a night shelter or supporting a food bank.\n\nSecond way: Belief in a loving God gives Christians comfort and hope when they suffer. Even in illness or bereavement they trust that God cares for them personally and has not abandoned them, so they may turn to prayer and to their church community for support rather than despair.","evidence":["1 John 4:8","John 3:16","Agape love"],"examTip":"Make each way clearly separate, then add a second sentence that develops it (an example, consequence or reason).","answerTopic":"loving God influence"},{"id":"aqa-rs-a-christianity-paper1-1-1-5","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Explain two ways in which belief that God is just influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe God is just and wants a fair world, so they are influenced to campaign for justice themselves. For example, many support Fairtrade or charities such as Christian Aid which tackle the causes of poverty, following teachings like Amos 5:24 'let justice roll on like a river'.\n\nSecond way: Because God will judge everyone fairly, Christians try to live morally and take responsibility for their actions. Knowing they will be accountable (Matthew 25), they try to follow Jesus' teaching, confess their sins and make amends when they do wrong.","evidence":["Amos 5:24","Matthew 25:31–46","Micah 6:8"],"examTip":"'Influence' questions want what Christians actually DO or how they think/feel because of the belief.","answerTopic":"just God influence"},{"id":"aqa-rs-a-christianity-paper1-1-1-6","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Explain two Christian teachings about the omnipotence of God.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: God is all-powerful because he created the whole universe out of nothing. Genesis 1 describes God simply speaking ('Let there be light') and the world coming into being, showing that nothing is beyond his power. Many Christians therefore believe God sustains the universe at every moment.\n\nSecond teaching: God's power is shown in miracles and above all in raising Jesus from the dead. The Apostles' Creed begins 'I believe in God, the Father almighty, creator of heaven and earth', and Jesus taught 'with God all things are possible' (Matthew 19:26). For Christians this means God's power can overcome even death and sin.\n\nSource of authority applied: Matthew 19:26 shows Christians that no situation is hopeless, because God's power is unlimited — though most Christians add that God uses his power in a way consistent with his love and does not override human free will.","evidence":["Genesis 1:1–3","Matthew 19:26","Apostles' Creed: 'God, the Father almighty'"],"examTip":"To get the source mark fully, name the source AND explain what it shows about the teaching.","answerTopic":"omnipotence"},{"id":"aqa-rs-a-christianity-paper1-1-1-7","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"Explain two Christian responses to the problem of evil and suffering.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First response — free will: Many Christians argue that God gave humans free will so that they could freely choose to love him and others. Moral evil, such as war or cruelty, is the result of humans misusing that freedom. The story of the Fall (Genesis 3) shows Adam and Eve choosing to disobey God, bringing sin and suffering into the world. A world of genuine choice, they argue, is better than a world of robots.\n\nSecond response — suffering can have a purpose / trust in God: Some Christians, following thinkers such as Irenaeus and John Hick, believe suffering can help people develop virtues like courage, compassion and patience ('soul-making'). Others point to the Book of Job: Job suffers terribly but learns to trust God, whose ways are beyond human understanding (Job 38–42).\n\nPractical response: Christians also respond by praying for those who suffer and by helping them, as in the Parable of the Good Samaritan (Luke 10:25–37), and they believe God shares in suffering through Jesus on the cross.","evidence":["Genesis 3 (the Fall)","Book of Job 38–42","Irenaeus / John Hick 'soul-making'","Luke 10:25–37"],"examTip":"Name a specific text (e.g. Job or Genesis 3) and show how it answers the problem.","answerTopic":"evil and suffering responses"},{"id":"aqa-rs-a-christianity-paper1-1-1-8","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"‘The existence of evil and suffering proves that God is not loving.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nThe problem of evil, often traced back to Epicurus and developed by modern philosophers, argues that if God is omnipotent he could stop suffering, and if he is loving he would want to; yet suffering clearly exists. A loving parent would not allow their child to suffer pointlessly, so many people — including some who once believed — conclude that God either does not exist or is not loving.\n\nNatural evil is particularly difficult to explain. Free will can account for murder or war, but it cannot explain why innocent children die of cancer or why earthquakes kill thousands. If God designed the world, he chose to include processes that cause terrible suffering, which seems incompatible with love. Even the Bible contains cries like 'My God, my God, why have you forsaken me?' (Psalm 22:1), showing that believers themselves have felt abandoned.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMost Christians reject the statement. They argue that love requires freedom: God gave humans free will so that love could be real, and much suffering comes from human choices (Genesis 3). A loving God respects that freedom rather than controlling people like puppets.\n\nIrenaeus and John Hick suggested that the world is a 'vale of soul-making' in which suffering allows people to develop compassion, courage and forgiveness — qualities which could not exist in a world with no difficulties. Christians also point to Job, who learns that human beings cannot fully understand God's purposes.\n\nAbove all, Christians believe God has shown his love by entering suffering himself: 'For God so loved the world that he gave his one and only Son' (John 3:16). Jesus suffered and died on the cross, so God is not distant from pain. The resurrection and the promise that God 'will wipe every tear from their eyes' (Revelation 21:4) show suffering is not the final word.\n\nJUSTIFIED CONCLUSION\n\nThe statement says evil 'proves' God is not loving, which is too strong. The existence of suffering is a serious challenge, and natural evil in particular is hard to answer, so it is reasonable for someone to conclude that it makes belief in a loving God less likely. However, proof requires that there could be no good reason for God to allow suffering, and Christians offer several plausible reasons — free will, soul-making and God's sharing in suffering through Christ. I therefore conclude that evil and suffering raise a genuine question about God's love but do not prove that God is unloving.","evidence":["Epicurus' dilemma","Psalm 22:1","Genesis 3","Irenaeus / Hick 'vale of soul-making'","John 3:16","Revelation 21:4","Book of Job"],"examTip":"Pick up the key word in the statement ('proves') and use it in your conclusion — it often lets you reach a nuanced judgement.","answerTopic":"evil and a loving God"},{"id":"aqa-rs-a-christianity-paper1-1-1-9","paper":"Beliefs","module":"1.1","moduleTitle":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","question":"‘Belief in an omnipotent God is more important to Christians than belief in a loving God.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nOmnipotence underpins all other Christian beliefs. Without God's power there would be no creation ('In the beginning God created the heavens and the earth', Genesis 1:1), no miracles, no resurrection and no hope of eternal life. The Apostles' Creed begins with 'God, the Father almighty', suggesting that God's power is foundational.\n\nA loving God who lacked power could not actually save anyone. Christians trust that God can defeat sin and death because 'with God all things are possible' (Matthew 19:26). In this sense, God's love would make no practical difference to believers without the omnipotence to put that love into action.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany Christians would say that love is the very nature of God: 1 John 4:8 says 'God is love', and the Bible never defines God simply as power. Jesus summed up the whole law as loving God and loving your neighbour (Mark 12:30–31), so love is central to how Christians should live.\n\nThe heart of Christianity is the cross. On the cross God's power is shown not through force but through self-giving love: 'For God so loved the world that he gave his one and only Son' (John 3:16). Paul even says that God's power is 'made perfect in weakness' (2 Corinthians 12:9). This suggests Christians understand omnipotence through love, not the other way round.\n\nAn all-powerful God who did not love would be frightening rather than worthy of worship. Many Christians find comfort in suffering because they believe God loves them personally, not merely because he is powerful.\n\nLove also shapes how Christians live day to day. Believers are commanded to forgive, to care for the poor and to love their enemies (Matthew 5:44) because this reflects God's own character; belief in God's power alone would not produce this way of life.\n\nJUSTIFIED CONCLUSION\n\nBoth qualities matter, and many Christians would say it is a false choice because God's attributes are united — he is omnipotent, loving and just at once. However, I think the statement is mostly wrong. The New Testament places love at the centre of God's identity and of Christian ethics, and the cross shows that God's power is always exercised in love. Omnipotence is essential, but for most Christians it is God's love that gives his power its meaning and makes him worthy of worship.","evidence":["Genesis 1:1","Apostles' Creed","Matthew 19:26","1 John 4:8","John 3:16","Mark 12:30–31","2 Corinthians 12:9"],"examTip":"In 'more important' statements, compare the two things directly rather than writing two separate essays.","answerTopic":"omnipotence vs love"},{"id":"aqa-rs-a-christianity-paper1-1-2-0","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"Which one of the following is the Christian belief that God is three persons in one?\nA  The Incarnation\nB  The Atonement\nC  The Trinity\nD  The Resurrection","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C — The Trinity\n\nThe Trinity is the belief that the one God exists as three distinct persons — Father, Son and Holy Spirit — each fully God, yet not three gods. The Incarnation is God becoming human in Jesus; the Atonement is the restoring of the relationship between God and humanity; the Resurrection is Jesus rising from the dead.","evidence":["Nicene Creed","Matthew 28:19"],"examTip":"Watch for distractors that are also key Christian terms — be sure of each definition.","answerTopic":"Trinity"},{"id":"aqa-rs-a-christianity-paper1-1-2-1","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"At which event in the Gospels are all three persons of the Trinity described as present?\nA  The feeding of the 5000\nB  The baptism of Jesus\nC  The Last Supper\nD  The Ascension","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — The baptism of Jesus\n\nAt Jesus' baptism in the River Jordan, the Son is baptised, the Holy Spirit descends 'like a dove', and the Father's voice says 'You are my Son, whom I love' (Mark 1:10–11; Matthew 3:16–17). Christians often cite this as a biblical picture of the Trinity.","evidence":["Mark 1:9–11","Matthew 3:16–17"],"examTip":"The baptism of Jesus is the classic biblical illustration of the Trinity — learn it.","answerTopic":"baptism of Jesus Trinity"},{"id":"aqa-rs-a-christianity-paper1-1-2-2","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"Give one name for the third person of the Trinity.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"The Holy Spirit (also accept: the Holy Ghost / the Paraclete / the Advocate / the Comforter).","evidence":["John 14:26 'the Advocate, the Holy Spirit'"],"examTip":"Short-response items need one precise answer.","answerTopic":"Holy Spirit"},{"id":"aqa-rs-a-christianity-paper1-1-2-3","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"Give one quotation or teaching that shows Christians believe in only one God.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• 'Hear, O Israel: the Lord our God, the Lord is one' (the Shema, Deuteronomy 6:4, quoted by Jesus in Mark 12:29).\n• 'We believe in one God' (opening of the Nicene Creed).\n• 'You shall have no other gods before me' (Exodus 20:3).","evidence":["Deuteronomy 6:4","Mark 12:29","Nicene Creed","Exodus 20:3"],"examTip":"A short quotation with its reference is the most secure way to earn a 1-mark 'give one' teaching.","answerTopic":"oneness of God"},{"id":"aqa-rs-a-christianity-paper1-1-2-4","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"Explain two ways in which belief in the Trinity influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians worship God as Father, Son and Holy Spirit. For example, baptisms are carried out 'in the name of the Father and of the Son and of the Holy Spirit' (Matthew 28:19), and many services end with the Grace or a Trinitarian blessing, so the belief shapes the words of everyday worship and prayer.\n\nSecond way: Because the Trinity is a relationship of love between the three persons, Christians believe they are made for relationships too. This influences them to value community — belonging to a church family, caring for others and seeking unity — as a reflection of God's own nature. They may also pray to the Father, through the Son, in the power of the Spirit.","evidence":["Matthew 28:19","2 Corinthians 13:14 (the Grace)","Nicene Creed"],"examTip":"Show practical influence — worship, prayer, behaviour or community life.","answerTopic":"Trinity influence"},{"id":"aqa-rs-a-christianity-paper1-1-2-5","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"Explain two ways in which belief in the Holy Spirit influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe the Holy Spirit guides and strengthens them, as Jesus promised the Advocate would 'teach you all things' (John 14:26). This influences them to pray for guidance when making decisions and to trust that they are not alone when facing difficulties.\n\nSecond way: Many Christians believe the Spirit gives gifts and produces 'fruit' such as love, joy, peace and patience (Galatians 5:22–23). They try to develop these qualities in daily life, and in Pentecostal and charismatic churches worshippers may expect spiritual gifts such as speaking in tongues or healing during worship.","evidence":["John 14:26","Galatians 5:22–23","Acts 2 (Pentecost)"],"examTip":"Make each influence different — don't give two versions of 'it helps them'.","answerTopic":"Holy Spirit influence"},{"id":"aqa-rs-a-christianity-paper1-1-2-6","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"Explain two Christian teachings about the Trinity.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: There is only one God, but God exists as three distinct persons — Father, Son and Holy Spirit. Christians stress they are not three gods; each person is fully God and shares the same divine nature. The Nicene Creed begins 'We believe in one God' and goes on to describe the Son as 'of one Being with the Father'.\n\nSecond teaching: Each person of the Trinity has a distinctive role. The Father is the creator and sustainer of all; the Son became human in Jesus to save humanity; the Holy Spirit is God's presence active in the world, guiding and strengthening believers. In the Nicene Creed the Spirit is 'the Lord, the giver of life, who proceeds from the Father [and the Son]'.\n\nSource applied: Jesus commanded his followers to baptise 'in the name of the Father and of the Son and of the Holy Spirit' (Matthew 28:19) — note 'name' is singular, which Christians see as showing the three persons are one God. (The words 'and the Son' — the filioque — are accepted by Catholic and most Protestant churches but not by the Orthodox Church.)","evidence":["Nicene Creed","Matthew 28:19","Mark 1:9–11","Filioque dispute"],"examTip":"The Nicene Creed is an excellent 'another source of Christian belief' — learn one line from it.","answerTopic":"Trinity teachings"},{"id":"aqa-rs-a-christianity-paper1-1-2-7","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"Explain two Christian teachings about God the Father and God the Son.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching — God the Father: Christians believe the Father is the creator of the universe and a loving parent who cares for every person. Jesus taught his disciples to pray 'Our Father in heaven' (Matthew 6:9), showing a close, personal relationship. The Apostles' Creed describes him as 'God, the Father almighty, creator of heaven and earth'.\n\nSecond teaching — God the Son: Jesus is the Son of God, fully divine and fully human, who became incarnate to save humanity. He is not a created being but eternally one with the Father: 'I and the Father are one' (John 10:30). The Nicene Creed calls him 'eternally begotten of the Father… of one Being with the Father'.\n\nApplication: These teachings mean Christians can relate to God both as a caring parent and through Jesus, who reveals what God is like — 'Anyone who has seen me has seen the Father' (John 14:9).","evidence":["Matthew 6:9","Apostles' Creed","John 10:30","John 14:9","Nicene Creed"],"examTip":"Develop each teaching with what it means for Christians, not just a description.","answerTopic":"Father and Son"},{"id":"aqa-rs-a-christianity-paper1-1-2-8","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"‘The Trinity is too difficult for Christians to understand.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nThe Trinity seems to break ordinary logic: one God who is three persons, each fully God, yet not three gods. Even great theologians have admitted it is a mystery. St Augustine wrote an entire book, De Trinitate, trying to explain it, and the Church itself calls it a mystery of faith that human reason could never discover on its own.\n\nThe word 'Trinity' does not appear in the Bible. The doctrine was defined later, at the Councils of Nicaea (325) and Constantinople (381), after centuries of argument. If the early Church took so long to agree, and the churches still disagree over details such as the filioque (whether the Spirit proceeds from the Father 'and the Son'), it is reasonable to say ordinary Christians may struggle to understand it.\n\nAnalogies often used — water as ice, liquid and steam; or a shamrock — are imperfect and can lead to errors such as modalism (one God wearing three 'masks'). Non-Christians, such as Muslims and Jews, sometimes see the Trinity as compromising belief in one God.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nChristians argue that they do not need to understand everything about God to understand enough. The basic teaching is clear: one God (Deuteronomy 6:4) who is Father, Son and Holy Spirit (Matthew 28:19). Christians experience God in these three ways — as creator and loving Father, through Jesus, and through the Spirit at work in their lives.\n\nThe Trinity is learned through worship rather than abstract theory. Christians are baptised in the name of the Trinity, recite the Nicene Creed, and pray the Grace (2 Corinthians 13:14). The doctrine is lived, not merely studied, so most believers understand it in practice.\n\nMany Christians say that if God were simple enough to understand completely, he would not be God. A finite mind cannot fully grasp an infinite being, so mystery is exactly what you would expect.\n\nJUSTIFIED CONCLUSION\n\nIt is true that the Trinity cannot be fully understood — the Church itself says so. However, the statement suggests it is 'too difficult', implying Christians cannot understand it at all. I disagree: the central idea is clearly expressed in scripture and the creeds, and Christians grasp it through worship and experience. The Trinity is a mystery to be explored rather than a puzzle to be solved, so it is difficult but not too difficult for Christian faith.","evidence":["Deuteronomy 6:4","Matthew 28:19","2 Corinthians 13:14","Nicene Creed (325/381)","Augustine, De Trinitate","Filioque"],"examTip":"Distinguish between 'understand fully' and 'understand enough' — that distinction gives a strong conclusion.","answerTopic":"Trinity understanding"},{"id":"aqa-rs-a-christianity-paper1-1-2-9","paper":"Beliefs","module":"1.2","moduleTitle":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","question":"‘Belief in the Holy Spirit is the most important part of the Trinity for Christians today.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nThe Holy Spirit is God at work in the lives of Christians now. Jesus promised that after he left, the Father would send 'the Advocate, the Holy Spirit' to teach and remind believers (John 14:26). Jesus has ascended, so for Christians today it is the Spirit who brings God's presence into daily life.\n\nThe Church itself began when the Spirit came at Pentecost (Acts 2), giving the disciples courage to preach. Christians believe the Spirit continues to guide the Church, inspire scripture, give gifts and produce the 'fruit of the Spirit' (Galatians 5:22–23). Pentecostal and charismatic Christians, one of the fastest-growing groups worldwide, place particular emphasis on the Spirit's power in worship, healing and speaking in tongues.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nChristians believe the three persons are equal: no person of the Trinity is more important than another. The Athanasian Creed says 'none is before or after another; none is greater or less than another'. To make one person 'most important' could distort the doctrine.\n\nMany Christians would say Jesus the Son is central, because salvation comes through his death and resurrection (John 3:16), and Christianity is named after Christ. The Spirit's role is to point people to Jesus (John 15:26). Others emphasise God the Father as creator, to whom Jesus himself prayed ('Our Father', Matthew 6:9).\n\nCatholic and Orthodox Christians experience the Spirit mainly through the sacraments and the Church's tradition, rather than as a separate focus. For them the Spirit cannot be separated from the work of Father and Son.\n\nJUSTIFIED CONCLUSION\n\nThere is a strong case that the Spirit is the person of the Trinity Christians most directly experience today, especially in Pentecostal traditions. However, Christian teaching is clear that the three persons are co-equal and work together: the Father sends, the Son saves and the Spirit makes that salvation real in believers. I therefore conclude that the Spirit is extremely important to Christians today, but it is not accurate to call it the 'most important' part of the Trinity, because that contradicts the very idea of three equal persons in one God.","evidence":["John 14:26","Acts 2","Galatians 5:22–23","Athanasian Creed","John 3:16","John 15:26","Matthew 6:9"],"examTip":"Use differences between Christian traditions (e.g. Pentecostal vs Orthodox) — it shows the diversity examiners reward.","answerTopic":"Holy Spirit importance"},{"id":"aqa-rs-a-christianity-paper1-1-3-0","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"Which one of the following opens with the words 'In the beginning was the Word'?\nA  Genesis 1\nB  John 1\nC  Matthew 1\nD  Revelation 1","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — John 1\n\nJohn 1:1 begins 'In the beginning was the Word, and the Word was with God, and the Word was God.' John deliberately echoes Genesis 1:1 ('In the beginning God created…'), but Genesis does not mention 'the Word' by name. Christians understand the Word (Greek: Logos) to be Jesus, the Son.","evidence":["John 1:1–3","Genesis 1:1"],"examTip":"Know the opening words of both prescribed passages: Genesis 1:1–3 and John 1:1–3.","answerTopic":"the Word"},{"id":"aqa-rs-a-christianity-paper1-1-3-1","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"In Genesis 1:2, what was 'hovering over the waters'?\nA  The Word of God\nB  An angel\nC  The Spirit of God\nD  The light","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C — The Spirit of God\n\nGenesis 1:2 says 'the Spirit of God was hovering over the waters.' Christians see this as the Holy Spirit present and active in creation. The Word is in John 1; light is created in Genesis 1:3.","evidence":["Genesis 1:2"],"examTip":"The prescribed texts are examinable in detail — learn the key phrase from each verse.","answerTopic":"Spirit in creation"},{"id":"aqa-rs-a-christianity-paper1-1-3-2","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"Give one thing the prologue of John's Gospel teaches about the Word.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• The Word existed 'in the beginning' (was eternal / not created).\n• The Word was with God and the Word was God (John 1:1).\n• 'Through him all things were made' — the Word was the agent of creation (John 1:3).\n• The Word became flesh — Jesus (John 1:14).","evidence":["John 1:1–3","John 1:14"],"examTip":"Any accurate point from John 1:1–3 will earn the mark.","answerTopic":"Word in John"},{"id":"aqa-rs-a-christianity-paper1-1-3-3","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"Give one way in which some Christians interpret the Genesis creation account.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• Literally — God created the world in six 24-hour days (creationism / Young Earth creationism).\n• Symbolically / as a myth or poem expressing truths about God, not scientific fact.\n• As compatible with science — God started the Big Bang and works through evolution (theistic evolution / the 'days' as long ages).","evidence":["Genesis 1","Young Earth creationism","Theistic evolution"],"examTip":"Use a precise label if you can (e.g. 'literalist'), but a clear description also gains the mark.","answerTopic":"creation interpretation"},{"id":"aqa-rs-a-christianity-paper1-1-3-4","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"Explain two ways in which Christian beliefs about creation influence Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe God created the world and saw that it was 'very good' (Genesis 1:31) and gave humans responsibility to care for it (Genesis 2:15). This influences them to act as stewards — recycling, reducing their carbon footprint, or joining projects such as A Rocha or the Eco Church scheme.\n\nSecond way: Because the Bible says humans were made 'in the image of God' (Genesis 1:27), Christians believe every person has equal dignity and worth. This influences them to treat all people with respect, oppose discrimination and protect human life, for example by caring for the vulnerable.","evidence":["Genesis 1:27","Genesis 1:31","Genesis 2:15","A Rocha / Eco Church"],"examTip":"Influence = a belief → a practical effect. Name a real example to develop the point.","answerTopic":"creation influence"},{"id":"aqa-rs-a-christianity-paper1-1-3-5","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"Explain two ways in which belief that God created through his Word influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Christians believe Jesus is the Word through whom 'all things were made' (John 1:3), they see Jesus not just as a teacher but as God, present at creation. This influences them to worship Jesus and to give his teachings supreme authority in how they live.\n\nSecond way: Genesis shows God creating simply by speaking ('And God said…'), so Christians believe God's word has power. This influences them to value the Bible as the Word of God, reading it regularly in private devotion and in church services, and trusting its promises.","evidence":["John 1:1–3","Genesis 1:3","2 Timothy 3:16"],"examTip":"Link the 'Word' to both Jesus and the power of God's speech/the Bible.","answerTopic":"Word influence"},{"id":"aqa-rs-a-christianity-paper1-1-3-6","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"Explain two Christian teachings about the role of the Word and the Spirit in creation.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching — the Word: John 1:1–3 teaches 'In the beginning was the Word… Through him all things were made; without him nothing was made that has been made.' Christians believe the Word is the Son, Jesus, who existed eternally with God and was the means through which God created everything. This shows Jesus was not created but was active in creation as God.\n\nSecond teaching — the Spirit: Genesis 1:2 describes 'the Spirit of God hovering over the waters' before God speaks. Christians interpret this as the Holy Spirit giving life and order to the formless world. The Nicene Creed calls the Spirit 'the giver of life'.\n\nApplication: Together these passages show Christians that the whole Trinity was involved in creation — the Father creating, through the Word, by the power of the Spirit. Many Christians therefore see the universe as an expression of God's love and order rather than an accident.","evidence":["John 1:1–3","Genesis 1:1–3","Nicene Creed 'the giver of life'"],"examTip":"These two passages are named in the specification — quote them accurately.","answerTopic":"Word and Spirit"},{"id":"aqa-rs-a-christianity-paper1-1-3-7","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"Explain two different Christian beliefs about how the world was created.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First belief — literal creation: Some Christians, especially some evangelical Protestants, read Genesis 1 literally. They believe God created the universe in six 24-hour days a few thousand years ago and rested on the seventh (Genesis 2:2). They reject evolution where it contradicts scripture, because they believe the Bible is the inerrant Word of God.\n\nSecond belief — non-literal / theistic evolution: Most Christians, including the Catholic Church and the Church of England, see Genesis as a theological account teaching WHY the world exists and WHO created it, not HOW. They accept the Big Bang and evolution as the means God used. Pope Francis said God 'created beings and allowed them to develop according to the internal laws he gave to each one' (2014).\n\nShared ground: Both views agree with Genesis 1:1 'In the beginning God created the heavens and the earth' — that God is the ultimate cause of the universe and that it is good (Genesis 1:31).","evidence":["Genesis 1:1–2:3","Genesis 1:31","Pope Francis, Pontifical Academy of Sciences 2014","Georges Lemaître (Big Bang, Catholic priest)"],"examTip":"If asked for 'different' beliefs, make the contrast explicit.","answerTopic":"creation views"},{"id":"aqa-rs-a-christianity-paper1-1-3-8","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"‘The Bible's account of creation should be taken literally.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nSome Christians, often called creationists or literalists, believe the Bible is the inspired and inerrant Word of God: 'All Scripture is God-breathed' (2 Timothy 3:16). If God inspired Genesis, it should be accepted as it stands — God created the world in six days and rested on the seventh. Reinterpreting it to fit science, they argue, puts human ideas above God's word.\n\nLiteralists also point out that other parts of the Bible treat creation as historical. Jesus refers to God making humans 'male and female' 'at the beginning' (Matthew 19:4), and the Sabbath commandment is based on the six days of creation (Exodus 20:11). If these are not literal, it might undermine trust in other teachings, such as the Fall and the need for salvation.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMost Christians — including the Catholic Church, the Church of England and the Orthodox Church — do not read Genesis literally. They argue it is a theological account explaining WHO made the world and WHY, not a scientific record. Its poetic structure (a refrain 'And there was evening, and there was morning') and the fact that Genesis 1 and 2 describe creation in different orders suggest it was not meant as a literal timetable.\n\nScience provides strong evidence for a 13.8-billion-year-old universe and for evolution. Many Christian scientists, such as Georges Lemaître (a Catholic priest who proposed the Big Bang theory) and Francis Collins, see no conflict between science and faith. Augustine, as early as the 5th century, warned Christians against interpreting Genesis in ways that contradict what can be known about the natural world.\n\nJohn 1:1–3 adds that God created through the Word and Genesis 1:2 speaks of the Spirit — this is a profound truth about God's nature rather than a description of physical processes.\n\nJUSTIFIED CONCLUSION\n\nLiteralists are right to take the Bible seriously as God's word, and the statement reflects a sincere desire to trust scripture. However, taking the Bible seriously is not the same as taking every passage literally. The literary style of Genesis and the weight of scientific evidence suggest it is better understood as true about God and humanity rather than as a scientific account. I therefore disagree with the statement: the central message — that God created a good world with purpose — matters more than a literal six-day timescale.","evidence":["2 Timothy 3:16","Matthew 19:4","Exodus 20:11","Genesis 1–2","John 1:1–3","Georges Lemaître","Augustine, The Literal Meaning of Genesis"],"examTip":"Avoid saying 'Christians believe…' as if all agree; name which Christians hold each view.","answerTopic":"literal creation"},{"id":"aqa-rs-a-christianity-paper1-1-3-9","paper":"Beliefs","module":"1.3","moduleTitle":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","question":"‘Science has proved that the Christian belief in creation is wrong.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nScientific evidence shows the universe began around 13.8 billion years ago with the Big Bang, and life developed over billions of years through evolution by natural selection, as Charles Darwin argued. This contradicts a literal reading of Genesis, in which the world is made in six days and humans are created fully formed. For those who think Christianity requires a literal Genesis, science has disproved it.\n\nAtheist scientists such as Richard Dawkins argue that natural processes explain the complexity of life without any need for a creator, and Stephen Hawking suggested the laws of physics could explain how the universe began. If science can explain the origin of everything, belief in a creator God seems unnecessary.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMost Christians argue that science and religion answer different questions. Science explains HOW the universe developed; Christian teaching explains WHY it exists and WHO is ultimately responsible. Genesis 1:1 'In the beginning God created the heavens and the earth' is not contradicted by the Big Bang — indeed the Big Bang was first proposed by a Catholic priest, Georges Lemaître.\n\nThe Catholic Church and Church of England accept evolution as the way God created. Pope Francis stated that the Big Bang 'does not contradict the intervention of the divine creator but, rather, requires it', and that God allowed creatures to develop according to the laws he gave them.\n\nScience also cannot explain why there is something rather than nothing, or why the universe has laws that allow life. Many Christians see the order and fine-tuning of the universe as evidence of design. John 1:3 teaches that 'through him all things were made', which is a claim about ultimate cause that lies beyond scientific testing.\n\nJUSTIFIED CONCLUSION\n\nScience has disproved a strictly literal reading of Genesis, but that is only one Christian view. The central Christian belief — that God is the creator and sustainer of the universe — is not something science can prove or disprove, because science studies processes within the universe. Since most Christians accept scientific findings while still believing God is the creator, I conclude that science has not proved the Christian belief in creation wrong; rather, it has challenged particular interpretations of it.","evidence":["Genesis 1:1","John 1:3","Georges Lemaître","Pope Francis 2014","Charles Darwin","Richard Dawkins","Stephen Hawking"],"examTip":"A strong conclusion distinguishes between 'creation' as a belief and literal interpretation of Genesis.","answerTopic":"science and creation"},{"id":"aqa-rs-a-christianity-paper1-1-4-0","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Which one of the following is the Catholic belief in a state of cleansing after death before entering heaven?\nA  Purgatory\nB  Hell\nC  Limbo\nD  Paradise","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A — Purgatory\n\nPurgatory is the Catholic belief that some souls who die in God's friendship, but are not yet fully purified, undergo cleansing before entering heaven. Most Protestants reject purgatory because they see no clear biblical basis for it.","evidence":["Catechism of the Catholic Church 1030–1031"],"examTip":"Purgatory is a key example of Christian diversity — Catholic yes, most Protestants no.","answerTopic":"purgatory"},{"id":"aqa-rs-a-christianity-paper1-1-4-1","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Which one of the following passages describes the Parable of the Sheep and the Goats, about judgement?\nA  Luke 15\nB  Matthew 25\nC  John 3\nD  1 Corinthians 13","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Matthew 25\n\nMatthew 25:31–46 describes the Son of Man separating people 'as a shepherd separates the sheep from the goats'. Those who fed the hungry, welcomed strangers, clothed the naked and visited the sick and imprisoned are rewarded, because 'whatever you did for one of the least of these… you did for me'.","evidence":["Matthew 25:31–46"],"examTip":"Learn chapter references for the most-used parables — they make your 6-mark sources precise.","answerTopic":"sheep and goats"},{"id":"aqa-rs-a-christianity-paper1-1-4-2","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Give one Christian belief about hell.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• Hell is eternal separation from God.\n• Hell is a place/state of punishment for those who reject God ('eternal punishment', Matthew 25:46).\n• Hell is chosen by people who freely and finally reject God's love.\n• Some Christians believe hell is not a literal place of fire but a state of mind / that the unrepentant are destroyed (annihilation).","evidence":["Matthew 25:46","Catechism 1033"],"examTip":"One accurate belief earns the mark; you do not need to explain it.","answerTopic":"hell"},{"id":"aqa-rs-a-christianity-paper1-1-4-3","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Give one reason why belief in the resurrection of Jesus is important for Christian beliefs about life after death.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• Jesus' resurrection shows that death has been defeated / is not the end.\n• It is the 'firstfruits' — a promise that believers will also be raised (1 Corinthians 15:20).\n• Jesus said 'I am the resurrection and the life' (John 11:25).","evidence":["1 Corinthians 15:20","John 11:25"],"examTip":"Keep it to one clear reason.","answerTopic":"resurrection and afterlife"},{"id":"aqa-rs-a-christianity-paper1-1-4-4","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Explain two ways in which belief in life after death influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe they will be judged by God on how they lived (Matthew 25:31–46), so they try to live a moral life — for example by helping people in need, because Jesus taught that serving 'the least of these' is serving him. Belief in judgement gives their actions eternal significance.\n\nSecond way: Belief in resurrection and heaven gives Christians hope and comfort when facing death or bereavement. At funerals they pray and give thanks for the person's life, and many find peace knowing that death is not the end; Jesus promised 'I am the resurrection and the life' (John 11:25).","evidence":["Matthew 25:31–46","John 11:25–26","John 14:2"],"examTip":"Develop each way with a concrete example, e.g. charity work or a funeral.","answerTopic":"afterlife influence"},{"id":"aqa-rs-a-christianity-paper1-1-4-5","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Explain two ways in which belief in judgement influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe God will judge them for their actions and faith, so they try to follow Jesus' teaching closely — loving their neighbour, being honest and forgiving others. Catholics may go to the sacrament of Reconciliation (confession) to seek forgiveness for sins before judgement.\n\nSecond way: The Parable of the Sheep and the Goats (Matthew 25) teaches that people will be judged on how they treated the hungry, strangers, the sick and prisoners. This influences many Christians to volunteer with food banks, prison ministries or charities such as Christian Aid, seeing such service as serving Christ himself.","evidence":["Matthew 25:31–46","Romans 14:12","Sacrament of Reconciliation"],"examTip":"Use different examples for each way — one personal, one social works well.","answerTopic":"judgement influence"},{"id":"aqa-rs-a-christianity-paper1-1-4-6","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Explain two Christian teachings about resurrection.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Christians believe Jesus rose bodily from the dead on the third day, and that this proves death is defeated. Paul writes, 'Christ has indeed been raised from the dead, the firstfruits of those who have fallen asleep' (1 Corinthians 15:20) — just as the first fruits of harvest promise the rest of the crop, Jesus' resurrection promises that believers will also be raised.\n\nSecond teaching: Christians believe in the resurrection of the body, not just the survival of the soul. Paul teaches the resurrection body will be a transformed 'spiritual body' (1 Corinthians 15:42–44), imperishable and glorious. The Apostles' Creed states 'I believe in… the resurrection of the body, and the life everlasting.' Some Christians believe this happens at the end of time on the Day of Judgement; others believe the soul goes to God immediately at death and is reunited with a resurrected body later.\n\nApplication: Because of these teachings, Christians face death with hope; funeral services often include Jesus' words 'I am the resurrection and the life' (John 11:25).","evidence":["1 Corinthians 15:20","1 Corinthians 15:42–44","Apostles' Creed","John 11:25"],"examTip":"1 Corinthians 15 is the key text for resurrection — learn at least one verse.","answerTopic":"resurrection teachings"},{"id":"aqa-rs-a-christianity-paper1-1-4-7","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"Explain two Christian beliefs about heaven.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First belief: Heaven is eternal life in the presence of God, free from all suffering. Revelation describes a 'new heaven and a new earth' in which God 'will wipe every tear from their eyes. There will be no more death or mourning or crying or pain' (Revelation 21:1–4). Jesus promised his disciples, 'My Father's house has many rooms… I am going there to prepare a place for you' (John 14:2).\n\nSecond belief: Christians disagree about the nature of heaven. Some imagine it as a physical place of peace and beauty; many others, including Catholic teaching, describe it as a state of perfect happiness and union with God — the 'beatific vision' of seeing God face to face. There is also debate about who goes to heaven: some Christians believe only those with faith in Jesus are saved ('No one comes to the Father except through me', John 14:6), while others hope God's mercy extends more widely.\n\nApplication: Belief in heaven gives Christians hope and motivates them to live faithfully.","evidence":["Revelation 21:1–4","John 14:2","John 14:6","Catechism 1023–1029 (beatific vision)"],"examTip":"Show diversity: physical place vs spiritual state; exclusive vs inclusive views.","answerTopic":"heaven"},{"id":"aqa-rs-a-christianity-paper1-1-4-8","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"‘A loving God would not send people to hell.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nThe Bible teaches that 'God is love' (1 John 4:8) and that God 'wants all people to be saved' (1 Timothy 2:4). Many people argue that a loving parent would never punish their child forever, so eternal punishment seems incompatible with God's love. Some Christians therefore hold universalism — the hope that in the end everyone will be reconciled to God.\n\nEternal punishment for sins committed in a finite lifetime also seems disproportionate and unjust. Some Christians (such as some evangelicals who hold 'conditional immortality') believe the unrepentant are destroyed rather than tormented forever. Others understand hell symbolically, as the pain of being separated from God, not a literal place of fire.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nJesus himself spoke about hell. In the Parable of the Sheep and the Goats, those who failed to help others 'will go away to eternal punishment, but the righteous to eternal life' (Matthew 25:46). Traditional Christian teaching across Catholic, Orthodox and many Protestant churches accepts that hell is real.\n\nGod is not only loving but just. A just God cannot ignore evil — otherwise victims of terrible crimes would never see justice. Hell can be seen as part of God's justice.\n\nMany Christians argue that God does not 'send' anyone to hell; people choose it. The Catholic Catechism describes hell as 'the state of definitive self-exclusion from communion with God', and C.S. Lewis wrote that 'the doors of hell are locked on the inside'. Because God loves people he gives them free will, and respects even the choice to reject him. God offers forgiveness to everyone through Jesus (John 3:16).\n\nJUSTIFIED CONCLUSION\n\nThe statement is persuasive if hell is pictured as God actively torturing people against their will — that does seem hard to reconcile with a loving God. However, mainstream Christian teaching presents hell as the consequence of a person's free and final rejection of God, not as God forcing them there. On this understanding, the statement is right that God does not 'send' people to hell, but wrong to suggest a loving God would make hell impossible: love that respects freedom must allow people to say no. I therefore conclude that a loving God can permit hell, while hoping and working for every person's salvation.","evidence":["1 John 4:8","1 Timothy 2:4","Matthew 25:46","John 3:16","Catechism 1033","C.S. Lewis, The Problem of Pain"],"examTip":"Notice the word 'send' — questioning it is a good route to a nuanced conclusion.","answerTopic":"hell and a loving God"},{"id":"aqa-rs-a-christianity-paper1-1-4-9","paper":"Beliefs","module":"1.4","moduleTitle":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","question":"‘Belief in life after death is the most important Christian belief.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nPaul argues that the whole of Christianity depends on resurrection: 'if Christ has not been raised, your faith is futile… If only for this life we have hope in Christ, we are of all people most to be pitied' (1 Corinthians 15:17–19). Without the promise of eternal life, the central Christian message of salvation would be meaningless.\n\nBelief in the afterlife shapes how Christians live. Because they expect to be judged (Matthew 25:31–46), they try to love others and avoid sin. It gives hope in suffering and comfort at funerals, so for many ordinary believers it is the belief that matters most in practice. The creeds end with 'the resurrection of the body, and the life everlasting', showing it is where the whole of faith leads.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany Christians would argue that belief in God — particularly God as Trinity — is more fundamental. Without God there could be no afterlife at all; the first line of the creeds is 'I believe in God', not in heaven.\n\nOthers argue that belief in Jesus — his incarnation, death and resurrection — is the most important, because Christianity is centred on Christ and salvation comes through him (John 14:6). The afterlife is a consequence of what Jesus did, not the core of the faith itself.\n\nSome Christians worry that focusing on reward in heaven can make faith selfish. Jesus emphasised loving God and neighbour now (Mark 12:30–31), and taught that 'the kingdom of God is in your midst' (Luke 17:21). For many Christians, a relationship with God in this life matters more than speculation about the next.\n\nJUSTIFIED CONCLUSION\n\nBelief in life after death is clearly very important; Paul's argument in 1 Corinthians 15 shows Christianity would collapse without the resurrection. However, the hope of eternal life depends on prior beliefs about God and about Jesus — it is the result of the Christian story rather than its foundation. I therefore conclude that belief in life after death is one of the most important Christian beliefs, but belief in God revealed in Jesus is more fundamental, because the afterlife only makes sense in light of it.","evidence":["1 Corinthians 15:14–19","Matthew 25:31–46","Apostles' Creed","John 14:6","Mark 12:30–31","Luke 17:21"],"examTip":"For 'most important' statements, compare with at least one other named belief.","answerTopic":"importance of afterlife"},{"id":"aqa-rs-a-christianity-paper1-1-5-0","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Which one of the following best describes the incarnation?\nA  Jesus rising from the dead\nB  God becoming human in Jesus\nC  Jesus returning to heaven\nD  The Holy Spirit coming at Pentecost","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — God becoming human in Jesus\n\nThe incarnation (from Latin 'in carne', 'in flesh') is the belief that God the Son took on human nature and became a human being in Jesus, while remaining fully God: 'The Word became flesh and made his dwelling among us' (John 1:14). A is the resurrection, C is the ascension and D is Pentecost.","evidence":["John 1:14"],"examTip":"Learn crisp one-line definitions for incarnation, resurrection, ascension and atonement.","answerTopic":"incarnation"},{"id":"aqa-rs-a-christianity-paper1-1-5-1","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Which one of the following Gospels records the angel telling Mary 'the holy one to be born will be called the Son of God'?\nA  Mark\nB  Luke\nC  John\nD  Acts","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Luke\n\nLuke 1:35 records the angel Gabriel's words to Mary at the Annunciation: 'The Holy Spirit will come on you, and the power of the Most High will overshadow you. So the holy one to be born will be called the Son of God.' Mark and John do not include birth narratives, and Acts is not a Gospel.","evidence":["Luke 1:26–38","Matthew 1:18–25"],"examTip":"Only Matthew and Luke contain the birth stories of Jesus.","answerTopic":"Annunciation"},{"id":"aqa-rs-a-christianity-paper1-1-5-2","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Give one title used for Jesus that shows Christians believe he is divine.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: Son of God; the Word (Logos); Lord; Emmanuel ('God with us', Matthew 1:23); the Christ/Messiah (accept, as Christians understand this title); God the Son.","evidence":["Matthew 1:23","John 1:1","Mark 1:1"],"examTip":"A single title is enough.","answerTopic":"titles of Jesus"},{"id":"aqa-rs-a-christianity-paper1-1-5-3","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Give one reason why Christians believe Jesus was fully human.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• He was born of a human mother, Mary.\n• He experienced hunger, tiredness and thirst.\n• He wept at the death of Lazarus (John 11:35).\n• He felt pain and died on the cross.\n• He was tempted (Matthew 4:1–11).","evidence":["John 11:35","Matthew 4:1–11","Luke 2:7"],"examTip":"Pick a concrete Gospel detail.","answerTopic":"humanity of Jesus"},{"id":"aqa-rs-a-christianity-paper1-1-5-4","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Explain two ways in which belief in the incarnation influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Christians believe God became human in Jesus, they see Jesus' life as the perfect example of how to live. They try to copy his compassion, forgiveness and humility, for example by caring for the sick and marginalised as he did, asking 'What would Jesus do?'\n\nSecond way: Belief that God 'became flesh' (John 1:14) shows that God values human life and the physical world. This influences Christians to treat every person with dignity, to celebrate Christmas as a major festival of God's love, and to feel that God understands their struggles because he lived a human life — giving them confidence to pray.","evidence":["John 1:14","Hebrews 4:15","Philippians 2:5–8"],"examTip":"Each way should describe a real-life effect on belief or behaviour.","answerTopic":"incarnation influence"},{"id":"aqa-rs-a-christianity-paper1-1-5-5","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Explain two ways in which belief that Jesus is the Son of God influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Jesus is the Son of God, Christians worship him and pray to him or through him, ending many prayers 'through Jesus Christ our Lord'. His words carry divine authority, so Christians treat the Gospels as central to worship — standing for the Gospel reading in many churches.\n\nSecond way: Christians believe that through Jesus, the Son, they can become children of God themselves (John 1:12). This gives them a sense of identity and belonging in God's family, encouraging them to treat other Christians as brothers and sisters and to share their faith with others through evangelism.","evidence":["John 1:12","Mark 1:11","John 20:31"],"examTip":"Use specific worship practices to develop points.","answerTopic":"Son of God influence"},{"id":"aqa-rs-a-christianity-paper1-1-5-6","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Explain two Christian teachings about the incarnation.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Jesus is fully God and fully human. John's Gospel teaches 'The Word became flesh and made his dwelling among us' (John 1:14) — the eternal Word, who 'was God' (John 1:1), took on a real human body and nature. The Council of Chalcedon (451) taught that Jesus has two natures, divine and human, united in one person, without mixing or confusion.\n\nSecond teaching: Jesus was conceived by the Holy Spirit and born of the Virgin Mary. Matthew's Gospel says Mary 'was found to be pregnant through the Holy Spirit' (Matthew 1:18), and calls him 'Immanuel — which means \"God with us\"' (Matthew 1:23). This shows the incarnation was a miraculous act of God, not an ordinary birth.\n\nApplication: These teachings mean Christians believe God truly entered human life to save humanity; because Jesus shared human experience, 'we do not have a high priest who is unable to empathise with our weaknesses' (Hebrews 4:15).","evidence":["John 1:1, 14","Matthew 1:18–23","Luke 1:35","Council of Chalcedon (451)","Hebrews 4:15"],"examTip":"Name the gospel and verse, then say what it shows — this secures both source marks.","answerTopic":"incarnation teachings"},{"id":"aqa-rs-a-christianity-paper1-1-5-7","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"Explain two Christian teachings about Jesus as the Son of God.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Jesus has a unique relationship with God the Father. At his baptism a voice from heaven said, 'You are my Son, whom I love; with you I am well pleased' (Mark 1:11). Christians believe this shows Jesus is the divine Son, not merely a good man or prophet.\n\nSecond teaching: As Son of God, Jesus is equal with the Father and shares his divine nature. Jesus said 'I and the Father are one' (John 10:30), and the Nicene Creed calls him 'the only Son of God, eternally begotten of the Father… true God from true God… of one Being with the Father'. Christians believe this means Jesus can reveal God perfectly and has the authority to forgive sins.\n\nApplication: Jesus' miracles and resurrection are seen as signs of this identity; John wrote his Gospel 'that you may believe that Jesus is the Messiah, the Son of God' (John 20:31).","evidence":["Mark 1:11","John 10:30","Nicene Creed","John 20:31"],"examTip":"'Son of God' does not mean God had a child biologically — show you understand the theological meaning.","answerTopic":"Son of God teachings"},{"id":"aqa-rs-a-christianity-paper1-1-5-8","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"‘Jesus was just a good teacher, not the Son of God.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nMany non-religious people and some other faiths accept that Jesus was a real historical figure who taught powerful moral lessons — love your enemies, forgive, care for the poor — but deny he was divine. Humanists, for example, admire his ethics without accepting supernatural claims. Muslims revere Jesus (Isa) as a great prophet, but reject the idea that God has a son.\n\nSome scholars argue that the title 'Son of God' was used in Jewish tradition for kings and righteous people, and that belief in Jesus' full divinity developed later in the early Church, being formally defined at Nicaea in 325. Miracle stories and the virgin birth cannot be proved scientifically, so a sceptic might conclude Jesus was an inspiring human being whose followers later exalted him.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nChristians believe the Gospels clearly present Jesus as more than a teacher. At his baptism the Father declares 'You are my Son' (Mark 1:11); Jesus forgives sins, which only God can do (Mark 2:5–7); and he claims 'I and the Father are one' (John 10:30). John's Gospel opens by identifying Jesus as the eternal Word who 'was God' (John 1:1, 14).\n\nC.S. Lewis argued that Jesus cannot simply have been a good teacher: someone who claimed to be God would either be lying, deluded, or telling the truth ('liar, lunatic or Lord'). A merely human teacher who made such claims would not be 'good'.\n\nAbove all, Christians point to the resurrection. Paul lists many witnesses who saw the risen Jesus (1 Corinthians 15:3–8), and the disciples, once frightened, were willing to die for their belief. Christians argue this transformation is best explained if Jesus really is the Son of God. Catholic, Orthodox and Protestant Christians all affirm in the Nicene Creed that he is 'true God from true God'.\n\nJUSTIFIED CONCLUSION\n\nFrom a non-religious perspective the statement is understandable, since the divinity of Jesus cannot be proved. However, the statement says Jesus was 'just' a good teacher, and this fits poorly with the evidence of the Gospels, where his teaching is bound up with claims about his own identity. If those claims were false, his goodness would be questionable. From a Christian standpoint, and considering Lewis's argument, I conclude that it is more coherent to see Jesus either as far more than a teacher or as something other than 'good' — and Christians, on the basis of scripture and the resurrection, believe he is the Son of God.","evidence":["Mark 1:11","Mark 2:5–7","John 1:1, 14","John 10:30","1 Corinthians 15:3–8","C.S. Lewis, Mere Christianity","Nicene Creed"],"examTip":"Include a non-religious or other-faith view for the 'different point of view' — it is credited.","answerTopic":"Jesus' identity"},{"id":"aqa-rs-a-christianity-paper1-1-5-9","paper":"Beliefs","module":"1.5","moduleTitle":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","question":"‘The incarnation is the most important event in Christianity.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nWithout the incarnation, nothing else in the Christian story could happen. Jesus could not die on the cross or rise from the dead unless God had first become human. John 1:14 — 'The Word became flesh' — is the starting point of salvation. Athanasius argued that God became human so that humans could share in God's life; for him the incarnation itself begins to heal humanity.\n\nThe incarnation shows the depth of God's love: God did not stay distant but entered the world as a vulnerable baby. It reveals what God is like ('Anyone who has seen me has seen the Father', John 14:9) and means God understands human suffering from the inside (Hebrews 4:15). Christmas is the most widely celebrated Christian festival in Britain, showing its importance to many people.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMost Christians would say that the crucifixion and resurrection are more important. Paul says 'if Christ has not been raised, your faith is futile' (1 Corinthians 15:17), and that he preached 'Christ crucified' (1 Corinthians 1:23). The cross is the main symbol of Christianity, not the manger. Easter, not Christmas, is the oldest and holiest Christian festival.\n\nChristians believe salvation comes through Jesus' death as an atonement for sin (Mark 10:45) and that the resurrection proves victory over death. The incarnation is the means to this end: Jesus was born in order to die and rise again.\n\nSome Christians, such as Pentecostals, would also stress Pentecost as vital, since it is when the Spirit came and the Church was born (Acts 2).\n\nJUSTIFIED CONCLUSION\n\nThe incarnation is essential — without it there would be no Jesus and no salvation — and it profoundly shows God's love. However, the statement claims it is the 'most important event'. Scripture and Christian worship place the death and resurrection at the centre: Easter is the greatest festival and the cross is the universal symbol. I conclude that the incarnation, crucifixion and resurrection form one connected story of salvation, but if one event must be chosen, the resurrection is more important because it confirms Jesus' identity and the hope of eternal life.","evidence":["John 1:14","John 14:9","Hebrews 4:15","Athanasius, On the Incarnation","1 Corinthians 15:17","1 Corinthians 1:23","Mark 10:45","Acts 2"],"examTip":"Consider how events link together — evaluating relationships between beliefs is a higher-level skill.","answerTopic":"importance of incarnation"},{"id":"aqa-rs-a-christianity-paper1-1-6-0","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"Which one of the following is the event when Jesus returned to his Father in heaven forty days after the resurrection?\nA  The Transfiguration\nB  Pentecost\nC  The Ascension\nD  The Annunciation","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C — The Ascension\n\nThe Ascension is when the risen Jesus was 'taken up before their very eyes, and a cloud hid him from their sight' (Acts 1:9), forty days after Easter (Acts 1:3). Pentecost comes ten days later; the Transfiguration happened during his ministry; the Annunciation was before his birth.","evidence":["Acts 1:3–11","Luke 24:50–53"],"examTip":"Learn the order: crucifixion → resurrection (third day) → ascension (40 days) → Pentecost (50 days).","answerTopic":"ascension"},{"id":"aqa-rs-a-christianity-paper1-1-6-1","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"According to Luke's Gospel, what did Jesus say to the criminal crucified beside him who asked to be remembered?\nA  'Father, forgive them'\nB  'Today you will be with me in paradise'\nC  'It is finished'\nD  'I am thirsty'","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — 'Today you will be with me in paradise'\n\nIn Luke 23:43 Jesus says to the repentant criminal, 'Truly I tell you, today you will be with me in paradise.' 'Father, forgive them' is also in Luke (23:34) but is spoken about those crucifying him; 'It is finished' and 'I am thirsty' are in John 19.","evidence":["Luke 23:34, 43","John 19:28, 30"],"examTip":"Know which Gospel each 'word from the cross' comes from.","answerTopic":"words from the cross"},{"id":"aqa-rs-a-christianity-paper1-1-6-2","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"Give one event that happened at the crucifixion of Jesus according to the Gospels.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: Jesus was crucified between two criminals; a sign read 'King of the Jews'; darkness covered the land; Jesus forgave those who crucified him (Luke 23:34); he cried 'My God, my God, why have you forsaken me?' (Mark 15:34); the temple curtain was torn in two; a centurion said 'Surely this man was the Son of God!' (Mark 15:39); he was buried in a tomb belonging to Joseph of Arimathea.","evidence":["Mark 15:21–47","Luke 23:26–56"],"examTip":"Any accurate Gospel detail earns the mark.","answerTopic":"crucifixion events"},{"id":"aqa-rs-a-christianity-paper1-1-6-3","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"Give one piece of evidence the Gospels give for the resurrection of Jesus.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: the empty tomb discovered by women (Mark 16:1–8); appearances to Mary Magdalene (John 20:11–18); appearance to the disciples on the road to Emmaus (Luke 24); Thomas touching Jesus' wounds (John 20:24–29); Jesus eating fish with the disciples (Luke 24:42–43); Paul lists over 500 witnesses (1 Corinthians 15:6).","evidence":["Mark 16:1–8","John 20","Luke 24","1 Corinthians 15:3–8"],"examTip":"One clear example with a reference is ideal.","answerTopic":"resurrection evidence"},{"id":"aqa-rs-a-christianity-paper1-1-6-4","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"Explain two ways in which belief in the crucifixion of Jesus influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe Jesus died to take away their sins, so they feel forgiven and grateful. This influences them to confess their sins and to forgive others in turn, following Jesus' words on the cross, 'Father, forgive them, for they do not know what they are doing' (Luke 23:34). Examples include people like the families of victims who publicly forgive.\n\nSecond way: The cross is the central symbol of Christianity. Christians may wear a cross, make the sign of the cross, keep Good Friday solemnly and remember the crucifixion at every Eucharist. It also reminds them that God understands suffering, so they can find strength when they suffer themselves.","evidence":["Luke 23:34","Mark 15:34","1 Corinthians 1:18"],"examTip":"Develop the point with an example of practice or attitude.","answerTopic":"crucifixion influence"},{"id":"aqa-rs-a-christianity-paper1-1-6-5","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"Explain two ways in which belief in the ascension of Jesus influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Before ascending, Jesus told the disciples to 'go and make disciples of all nations' (Matthew 28:19) and that they would be his witnesses 'to the ends of the earth' (Acts 1:8). Christians therefore feel called to share their faith through evangelism and mission work, continuing what Jesus began.\n\nSecond way: Christians believe that Jesus ascended to be with the Father and 'will come back in the same way' (Acts 1:11). This gives them hope in the Second Coming and influences them to live ready for his return; it also reassures them that Jesus is with God interceding for them, so they pray with confidence. Ascension Day is celebrated in many churches.","evidence":["Acts 1:8–11","Matthew 28:19–20","Hebrews 7:25"],"examTip":"Link the ascension to mission and the Second Coming.","answerTopic":"ascension influence"},{"id":"aqa-rs-a-christianity-paper1-1-6-6","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"Explain two Christian teachings about the resurrection of Jesus.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Jesus physically rose from the dead on the third day. The women found the tomb empty and were told, 'He has risen! He is not here' (Mark 16:6). The risen Jesus appeared to many people — Mary Magdalene, the disciples, Thomas — and even ate with them (Luke 24:42–43), showing he was not a ghost.\n\nSecond teaching: The resurrection shows God's power over sin and death and promises eternal life to believers. Paul writes that 'Christ has indeed been raised from the dead, the firstfruits of those who have fallen asleep' (1 Corinthians 15:20) and that 'if Christ has not been raised, your faith is futile' (1 Corinthians 15:17). It confirms that Jesus is the Son of God.\n\nApplication: Christians celebrate the resurrection every Sunday and above all at Easter; for most, it is the foundation of their hope. (Some liberal Christians interpret it spiritually rather than physically, but the creeds affirm Jesus 'rose again'.)","evidence":["Mark 16:1–8","Luke 24:36–43","1 Corinthians 15:17, 20","Apostles' Creed"],"examTip":"Quote Paul in 1 Corinthians 15 to show why the resurrection matters.","answerTopic":"resurrection teachings"},{"id":"aqa-rs-a-christianity-paper1-1-6-7","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"Explain two Christian teachings about the crucifixion of Jesus.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Jesus' death was a sacrifice that dealt with human sin. Jesus said he came 'to give his life as a ransom for many' (Mark 10:45), and Paul writes that 'Christ died for our sins according to the Scriptures' (1 Corinthians 15:3). Christians believe his death restores the relationship between humanity and God (atonement).\n\nSecond teaching: Jesus suffered as a real human being, showing he fully shared human pain. Mark records him crying 'My God, my God, why have you forsaken me?' (Mark 15:34), quoting Psalm 22. Yet he also showed forgiveness: 'Father, forgive them, for they do not know what they are doing' (Luke 23:34). This teaches that God is present in suffering and that Christians should forgive even their enemies.\n\nApplication: At the moment of his death the temple curtain was torn (Mark 15:38), which Christians interpret as showing that the barrier between God and humanity had been removed.","evidence":["Mark 10:45","1 Corinthians 15:3","Mark 15:34, 38","Luke 23:34","Psalm 22"],"examTip":"Use details from the Gospel accounts to support your teaching.","answerTopic":"crucifixion teachings"},{"id":"aqa-rs-a-christianity-paper1-1-6-8","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"‘The resurrection is more important than the crucifixion for Christians.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nPaul argues that without the resurrection Christianity collapses: 'if Christ has not been raised, your faith is futile; you are still in your sins' (1 Corinthians 15:17). Many people died by crucifixion in the Roman world; what made Jesus unique was that he rose again. The resurrection proves that he is the Son of God and that his death really did defeat sin and death.\n\nThe resurrection gives Christians hope of eternal life. Jesus is 'the firstfruits' (1 Corinthians 15:20), so believers too will be raised. Easter Sunday is the greatest festival of the Christian year, and Sunday itself is the 'Lord's Day' because it is the day of resurrection. Orthodox Christians in particular emphasise the victory of the risen Christ, greeting one another with 'Christ is risen!'\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany Christians argue the crucifixion is more important because it is the moment when salvation happened. Jesus' death was 'a ransom for many' (Mark 10:45); 'Christ died for our sins' (1 Corinthians 15:3). Paul said he resolved to know nothing 'except Jesus Christ and him crucified' (1 Corinthians 2:2). The cross, not the empty tomb, is the universal Christian symbol.\n\nThe crucifixion also shows the depth of God's love — 'God demonstrates his own love for us in this: while we were still sinners, Christ died for us' (Romans 5:8). It speaks powerfully to people who suffer, showing God shares their pain. Many evangelical Protestants focus especially on the cross and the substitutionary atonement.\n\nChristians remember the crucifixion at every Eucharist ('do this in remembrance of me'), so it is at the heart of worship.\n\nJUSTIFIED CONCLUSION\n\nBoth arguments are strong, and most Christians would say the two events cannot be separated: the crucifixion deals with sin and the resurrection shows that it worked. A crucifixion without resurrection would be a tragedy; a resurrection without crucifixion would have nothing to overcome. However, if a choice must be made, I find the resurrection slightly more decisive, because as Paul argues it is what confirms the meaning of the cross. Still, the best Christian answer is that they are two halves of one saving event — the 'paschal mystery'.","evidence":["1 Corinthians 15:3, 17, 20","Mark 10:45","1 Corinthians 2:2","Romans 5:8","Luke 22:19"],"examTip":"When both sides are linked, say so — but still give a clear, justified decision.","answerTopic":"resurrection vs crucifixion"},{"id":"aqa-rs-a-christianity-paper1-1-6-9","paper":"Beliefs","module":"1.6","moduleTitle":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","question":"‘The ascension is not an important belief for Christians today.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nThe ascension receives much less attention than Christmas or Easter. Ascension Day falls on a Thursday and is little noticed in Britain outside regular churchgoers; many Christians might struggle to explain its meaning. Only Luke's writings (Luke 24 and Acts 1) describe it in detail.\n\nSome modern Christians find the idea of Jesus physically rising up into the sky difficult, since heaven is not literally 'up' above the clouds. They may see the account as symbolic and treat the resurrection as the decisive event, regarding the ascension as simply the end of the resurrection appearances.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nThe ascension is in both the Apostles' and Nicene Creeds: 'he ascended into heaven, and is seated at the right hand of the Father'. Christians all over the world affirm it every Sunday, so it is part of the core of faith.\n\nIt explains how Jesus' earthly mission ends and the Church's mission begins. Before ascending, Jesus said 'you will receive power when the Holy Spirit comes on you; and you will be my witnesses… to the ends of the earth' (Acts 1:8). Jesus also said that it was good for him to go away so the Advocate could come (John 16:7). Without the ascension there is no Pentecost and no worldwide Church. Mission and evangelism today are a direct response to this command.\n\nIt gives hope: the angels said 'This same Jesus… will come back in the same way you have seen him go into heaven' (Acts 1:11), which is the basis of belief in the Second Coming. It also teaches that Jesus, now with the Father, intercedes for believers (Hebrews 7:25) and that a human nature has been taken into heaven, a sign of the destiny God offers humanity.\n\nJUSTIFIED CONCLUSION\n\nIt is true that the ascension is less celebrated and less understood than other events, so in terms of popular attention the statement has some force. But importance should be judged by what a belief means, not how often it is celebrated. The ascension links the resurrection to Pentecost, launches the Church's mission and grounds hope in Christ's return. I therefore disagree with the statement: the ascension remains a significant belief for Christians today, even if many do not consciously focus on it.","evidence":["Acts 1:8–11","Luke 24:50–53","John 16:7","Hebrews 7:25","Apostles' Creed / Nicene Creed"],"examTip":"Separate 'important' from 'popular' — that helps you build a strong judgement.","answerTopic":"importance of ascension"},{"id":"aqa-rs-a-christianity-paper1-1-7-0","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"Which one of the following is the belief that all humans are born with a tendency to sin inherited from Adam and Eve?\nA  Free will\nB  Original sin\nC  Atonement\nD  Grace","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Original sin\n\nOriginal sin is the belief that the first sin of Adam and Eve (the Fall, Genesis 3) affected all humanity, so every person is born with a tendency to do wrong and is separated from God. Free will is the ability to choose; atonement is reconciliation with God; grace is God's free, undeserved love.","evidence":["Genesis 3","Romans 5:12"],"examTip":"Original sin is about a tendency/state humans are born with, not a sin a baby commits.","answerTopic":"original sin"},{"id":"aqa-rs-a-christianity-paper1-1-7-1","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"In Genesis 3, what did God tell Adam and Eve not to eat?\nA  Fruit from the tree of life\nB  Fruit from the tree of the knowledge of good and evil\nC  Any fruit in the garden\nD  Bread made from wheat","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Fruit from the tree of the knowledge of good and evil\n\nGod commanded Adam not to eat 'from the tree of the knowledge of good and evil' (Genesis 2:17). Tempted by the serpent, Eve ate and gave fruit to Adam (Genesis 3:6). They were then expelled from Eden.","evidence":["Genesis 2:16–17","Genesis 3:1–24"],"examTip":"Know the details of the Fall story — it is the basis of the original sin teaching.","answerTopic":"the Fall"},{"id":"aqa-rs-a-christianity-paper1-1-7-2","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"Give one meaning of 'sin' in Christianity.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: any thought or action that separates a person from God; disobeying God's will or law; 'missing the mark' of what God intends; a wrong action against God or other people.","evidence":["1 John 3:4","Romans 3:23"],"examTip":"A short definition is enough.","answerTopic":"sin definition"},{"id":"aqa-rs-a-christianity-paper1-1-7-3","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"Give one consequence of the Fall according to Genesis 3.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: Adam and Eve were expelled from the Garden of Eden; their relationship with God was broken; they felt shame/hid from God; pain in childbirth; hard work to grow food; death entered the world ('to dust you will return', Genesis 3:19); sin passed to all humanity (original sin).","evidence":["Genesis 3:16–24"],"examTip":"Any one consequence mentioned in Genesis 3 is credited.","answerTopic":"consequences of the Fall"},{"id":"aqa-rs-a-christianity-paper1-1-7-4","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"Explain two ways in which belief in sin influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Christians believe 'all have sinned and fall short of the glory of God' (Romans 3:23), they regularly seek forgiveness. Many churches include a prayer of confession in every service; Catholics may receive the sacrament of Reconciliation and be given absolution by a priest.\n\nSecond way: Belief in sin encourages Christians to examine their behaviour and try to resist temptation, following moral teachings such as the Ten Commandments and Jesus' Sermon on the Mount. They pray 'lead us not into temptation' in the Lord's Prayer and may avoid situations that could lead them to do wrong.","evidence":["Romans 3:23","1 John 1:9","Matthew 6:13","Exodus 20"],"examTip":"Show practical effects — confession, prayer, moral choices.","answerTopic":"sin influence"},{"id":"aqa-rs-a-christianity-paper1-1-7-5","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"Explain two ways in which belief in original sin influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Many Christians, especially Catholics, Orthodox and Anglicans, believe baptism washes away original sin, so they have their children baptised as babies. Infant baptism welcomes the child into the Church and God's grace from the start of life.\n\nSecond way: Belief in original sin reminds Christians that they cannot become good entirely through their own effort; they depend on God's grace and Jesus' saving death. This influences them to be humble, to pray for God's help and to be forgiving towards others, recognising that everyone has the same human weakness.","evidence":["Romans 5:12","Psalm 51:5","Catechism 1250 (infant baptism)"],"examTip":"Baptism is the clearest practical link to original sin.","answerTopic":"original sin influence"},{"id":"aqa-rs-a-christianity-paper1-1-7-6","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"Explain two Christian teachings about original sin.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Original sin began with the Fall in Genesis 3, when Adam and Eve disobeyed God by eating the forbidden fruit. Christians believe this broke the relationship between humanity and God and brought death and suffering into the world. Paul writes, 'sin entered the world through one man, and death through sin, and in this way death came to all people' (Romans 5:12).\n\nSecond teaching: Every human is born with original sin — an inherited tendency to do wrong and a condition of separation from God that they cannot overcome by themselves. Psalm 51:5 says 'Surely I was sinful at birth'. St Augustine developed this teaching. Catholic teaching says it is a 'state' rather than a personal act, and is washed away in baptism (Catechism 405).\n\nApplication: Christians believe the remedy is Jesus, the 'new Adam': 'For as in Adam all die, so in Christ all will be made alive' (1 Corinthians 15:22). Some Christians interpret Genesis 3 symbolically, as a story about the human condition rather than about two historical individuals.","evidence":["Genesis 3","Romans 5:12","Psalm 51:5","1 Corinthians 15:22","Augustine","Catechism 405"],"examTip":"Show you understand original sin as a condition inherited, not a personal crime.","answerTopic":"original sin teachings"},{"id":"aqa-rs-a-christianity-paper1-1-7-7","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"Explain two Christian teachings about sin and forgiveness.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: All people sin and fall short of God's standards. 'For all have sinned and fall short of the glory of God' (Romans 3:23). Sin can be thoughts, words or actions — Jesus taught that even anger and lust in the heart are sinful (Matthew 5:21–28). Sin damages a person's relationship with God and others.\n\nSecond teaching: God forgives those who truly repent. 'If we confess our sins, he is faithful and just and will forgive us our sins' (1 John 1:9). Jesus showed this in the Parable of the Lost Son (Luke 15:11–32), where the father runs to welcome back his son. Forgiveness is possible because of Jesus' death.\n\nApplication: Christians must forgive others as they are forgiven — 'forgive us our sins, as we forgive those who sin against us' (Lord's Prayer). Catholics receive forgiveness through the sacrament of Reconciliation; Protestants typically confess directly to God in private or corporate prayer.","evidence":["Romans 3:23","Matthew 5:21–28","1 John 1:9","Luke 15:11–32","Matthew 6:12"],"examTip":"Include a parable — it gives your teaching a clear, developed example.","answerTopic":"sin and forgiveness"},{"id":"aqa-rs-a-christianity-paper1-1-7-8","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"‘It is unfair that people are born with original sin.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nIt seems unjust that people should inherit guilt for something they did not do. A newborn baby has made no choices, so it seems wrong to say it is 'sinful'. Ezekiel 18:20 teaches that 'the child will not share the guilt of the parent', which appears to contradict the idea of inherited sin.\n\nMany people, including humanists, reject original sin as damaging, because it can make people feel guilty and worthless rather than encouraging them. Some Christians, too, interpret Genesis 3 symbolically, seeing Adam and Eve as representing every human rather than as ancestors who passed on sin. Pelagius, in the early Church, argued that humans are born innocent and can choose good; he was condemned, but his concern about fairness is still shared by some.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nChristian teaching does not usually say that babies are personally guilty. The Catholic Catechism explains original sin as a 'state' — a wounded human nature inclined to sin — rather than a personal act (Catechism 404–405). It is more like inheriting a condition than being punished for a crime.\n\nOriginal sin seems to fit human experience: every person, without exception, does wrong. Paul writes 'all have sinned' (Romans 3:23). The doctrine is a realistic explanation of why humans struggle to do good even when they want to ('I do not do the good I want to do', Romans 7:19).\n\nMost importantly, Christians believe God has not left humanity in this state. 'For as in Adam all die, so in Christ all will be made alive' (1 Corinthians 15:22). God's grace, offered freely to all through Jesus and through baptism, means no one is condemned simply because of original sin. Since the remedy is offered to everyone, the situation is not ultimately unfair.\n\nJUSTIFIED CONCLUSION\n\nIf original sin meant that God holds babies personally guilty and punishes them, it would indeed be unfair. But mainstream Christian teaching presents it as a description of the human condition — our tendency to sin — paired with God's free offer of grace to everyone. Understood this way, it is less a punishment than a diagnosis with a cure. I therefore disagree with the statement, while accepting that the traditional language of inherited 'guilt' can give a misleading impression.","evidence":["Genesis 3","Ezekiel 18:20","Romans 3:23","Romans 7:19","1 Corinthians 15:22","Catechism 404–405","Pelagius / Augustine"],"examTip":"Using a historical debate (Augustine v Pelagius) shows depth.","answerTopic":"fairness of original sin"},{"id":"aqa-rs-a-christianity-paper1-1-7-9","paper":"Beliefs","module":"1.7","moduleTitle":"Jesus Christ and salvation: sin, including original sin","question":"‘Humans are naturally good, not naturally sinful.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nGenesis teaches that humans were made 'in the image of God' (Genesis 1:27) and that God saw everything he made as 'very good' (Genesis 1:31). Christians who stress this believe human nature is fundamentally good, even if damaged. Every person can show love, creativity and conscience, reflecting God.\n\nMany people perform extraordinary acts of kindness and self-sacrifice — rescuers in disasters, carers, organ donors — including people with no religious faith. Humanists argue that humans are naturally social and compassionate, and that wrongdoing comes mainly from poor upbringing, poverty or circumstances, not from an inherited sinful nature.\n\nSome Christians also reject the traditional doctrine of original sin, preferring to see Genesis 3 as a symbolic story of human choice, and believing people are born innocent.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nTraditional Christian teaching, developed by Augustine and held by Catholic, Orthodox and most Protestant churches, says that because of the Fall humans are born with original sin — a tendency to do wrong. 'Surely I was sinful at birth' (Psalm 51:5); 'all have sinned and fall short of the glory of God' (Romans 3:23).\n\nHuman history supports this: war, genocide and cruelty appear in every culture. Paul describes the inner struggle everyone recognises: 'I do not do the good I want to do, but the evil I do not want to do — this I keep on doing' (Romans 7:19). Even good people find it hard to be consistently selfless.\n\nThis is why Christians believe humans need God's grace and salvation through Jesus; if people were naturally good, the cross would be unnecessary.\n\nJUSTIFIED CONCLUSION\n\nThe statement presents a false choice. Christian teaching holds both truths together: humans are created good, in God's image, but that goodness has been wounded by sin. Humans are therefore capable of great good and great evil. I conclude that the statement is partly right — human beings are fundamentally good in their creation — but wrong to deny the reality of sin, which both scripture and experience show is natural to fallen human nature.","evidence":["Genesis 1:27, 31","Psalm 51:5","Romans 3:23","Romans 7:19","Augustine","Humanist views"],"examTip":"A 'both/and' conclusion can be justified if you explain exactly how both are true.","answerTopic":"human nature"},{"id":"aqa-rs-a-christianity-paper1-1-8-0","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Which one of the following describes 'grace' in Christianity?\nA  A reward God gives for good works\nB  God's free and undeserved love and favour\nC  A set of religious rules\nD  A type of prayer said before meals only","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — God's free and undeserved love and favour\n\nGrace is God's free, unearned love and kindness towards humanity, shown above all in salvation through Jesus: 'For it is by grace you have been saved, through faith… it is the gift of God — not by works' (Ephesians 2:8–9). (A prayer before meals is sometimes called 'grace', but that is not the theological meaning.)","evidence":["Ephesians 2:8–9"],"examTip":"Be ready for distractors that use a word's everyday meaning.","answerTopic":"grace"},{"id":"aqa-rs-a-christianity-paper1-1-8-1","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Which one of the following is the Christian term for being saved from sin and its consequences?\nA  Salvation\nB  Incarnation\nC  Evangelism\nD  Ascension","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A — Salvation\n\nSalvation means being saved or delivered from sin and its consequences (including separation from God and death) and restored to a right relationship with God, leading to eternal life.","evidence":["John 3:16","Acts 4:12"],"examTip":"Salvation is the umbrella term for this whole topic.","answerTopic":"salvation"},{"id":"aqa-rs-a-christianity-paper1-1-8-2","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Give one way in which Christians believe salvation can be achieved.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: through faith in Jesus Christ; through God's grace; through the work of the Holy Spirit; by following God's law / doing good works (combined with faith); through the sacraments, e.g. baptism (Catholic/Orthodox view); by repenting of sin.","evidence":["Ephesians 2:8–9","James 2:17","John 3:5"],"examTip":"One clear method is enough.","answerTopic":"means of salvation"},{"id":"aqa-rs-a-christianity-paper1-1-8-3","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Give one reason why some Christians believe good works are needed for salvation.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: 'faith by itself, if it is not accompanied by action, is dead' (James 2:17); Jesus taught that people will be judged on how they treated others (Matthew 25:31–46); Jesus told the rich man to keep the commandments to enter life (Matthew 19:17); good works show that faith is genuine.","evidence":["James 2:17, 24","Matthew 25:31–46","Matthew 19:17"],"examTip":"Short and accurate — a reference strengthens it.","answerTopic":"works and salvation"},{"id":"aqa-rs-a-christianity-paper1-1-8-4","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Explain two ways in which belief in salvation by grace influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Christians believe salvation is a free gift they cannot earn (Ephesians 2:8–9), they respond with thankfulness and humility rather than pride. This influences them to worship joyfully, giving thanks to God in prayer and hymns such as 'Amazing Grace'.\n\nSecond way: Having received undeserved love from God, Christians feel called to show grace to others — forgiving people who hurt them and helping those who cannot repay them. For example, they may volunteer at a homeless shelter or support prisoners through organisations such as Prison Fellowship.","evidence":["Ephesians 2:8–9","Matthew 10:8 'Freely you have received; freely give'","'Amazing Grace' (John Newton)"],"examTip":"Link grace to gratitude and to how Christians treat others.","answerTopic":"grace influence"},{"id":"aqa-rs-a-christianity-paper1-1-8-5","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Explain two ways in which belief that the Holy Spirit helps bring salvation influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe the Spirit gives them new life and strength to change. Jesus said 'no one can enter the kingdom of God unless they are born of water and the Spirit' (John 3:5). This influences them to pray for the Spirit's help to overcome sin and to grow in the 'fruit of the Spirit' such as love, patience and self-control.\n\nSecond way: Many Christians believe they receive the Spirit through baptism and (for Catholics, Orthodox and Anglicans) confirmation, so they take part in these sacraments. In Pentecostal churches believers may seek a personal experience of the Spirit, such as 'baptism in the Spirit', during lively worship.","evidence":["John 3:5","Galatians 5:22–23","Acts 2:38"],"examTip":"Different traditions experience the Spirit differently — use that to develop your answer.","answerTopic":"Spirit influence"},{"id":"aqa-rs-a-christianity-paper1-1-8-6","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Explain two Christian teachings about how people are saved through law and grace.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching — law: God gave his law, such as the Ten Commandments (Exodus 20), to show people how to live rightly. Jesus taught 'If you want to enter life, keep the commandments' (Matthew 19:17) and that he came not to abolish the law but to fulfil it (Matthew 5:17). Many Christians, especially Catholics, teach that faith must be shown in obedience and good works: 'faith by itself, if it is not accompanied by action, is dead' (James 2:17).\n\nSecond teaching — grace: However, no one can keep the law perfectly, so salvation is ultimately God's gift. 'For it is by grace you have been saved, through faith — and this is not from yourselves, it is the gift of God — not by works, so that no one can boast' (Ephesians 2:8–9). Martin Luther emphasised salvation by grace through faith alone (sola fide), which became central to Protestant churches.\n\nApplication: Most Christians today agree that grace comes first, and that good works are a response to it, not a way of earning God's love.","evidence":["Exodus 20","Matthew 5:17","Matthew 19:17","James 2:17","Ephesians 2:8–9","Martin Luther (sola fide)"],"examTip":"This topic is ideal for showing Catholic/Protestant difference.","answerTopic":"law and grace"},{"id":"aqa-rs-a-christianity-paper1-1-8-7","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"Explain two Christian teachings about the role of the Holy Spirit in salvation.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: The Holy Spirit gives new spiritual life. Jesus told Nicodemus 'no one can enter the kingdom of God unless they are born of water and the Spirit' (John 3:5). Christians believe the Spirit makes them 'born again', changing them from within when they turn to God in faith and baptism.\n\nSecond teaching: The Spirit continues to guide and transform believers throughout their lives, helping them to live as God wants. Paul describes the 'fruit of the Spirit' — 'love, joy, peace, forbearance, kindness, goodness, faithfulness, gentleness and self-control' (Galatians 5:22–23). The Spirit also assures believers that they are God's children (Romans 8:16).\n\nApplication: Christians believe that salvation is the work of the whole Trinity — the Father's love, the Son's sacrifice, and the Spirit applying salvation to each person. At Pentecost Peter told the crowd, 'Repent and be baptised… And you will receive the gift of the Holy Spirit' (Acts 2:38).","evidence":["John 3:5–8","Galatians 5:22–23","Romans 8:16","Acts 2:38"],"examTip":"Name the 'fruit of the Spirit' accurately; it's a well-known source.","answerTopic":"Spirit and salvation"},{"id":"aqa-rs-a-christianity-paper1-1-8-8","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"‘Christians can only be saved by faith, not by good works.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nPaul teaches 'For it is by grace you have been saved, through faith… not by works, so that no one can boast' (Ephesians 2:8–9). If salvation could be earned by good deeds, it would no longer be a gift, and people might become proud. Because 'all have sinned' (Romans 3:23), no one can do enough good to make up for sin.\n\nMartin Luther, the Protestant reformer, rediscovered this teaching in Romans 1:17 ('the righteous will live by faith') and made sola fide (faith alone) a central principle of the Reformation. Many Protestant and evangelical Christians hold this view today. The criminal crucified next to Jesus had no chance to do good works, yet Jesus promised him paradise because of his faith (Luke 23:43).\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nJames writes, 'faith by itself, if it is not accompanied by action, is dead' and 'a person is considered righteous by what they do and not by faith alone' (James 2:17, 24). Jesus' Parable of the Sheep and the Goats (Matthew 25:31–46) shows people judged on whether they fed the hungry and cared for the sick.\n\nThe Catholic Church teaches that salvation is by God's grace, received through faith and the sacraments, and that genuine faith must express itself in love and good works. The Council of Trent rejected 'faith alone'. Orthodox Christians speak of salvation as a lifelong process of becoming like God (theosis), in which human effort cooperates with grace.\n\nMany Christians also stress the role of the Spirit and the law: the Spirit transforms believers so that they keep God's commands.\n\nJUSTIFIED CONCLUSION\n\nThe disagreement is narrower than it first appears. In 1999 the Catholic Church and the Lutheran World Federation signed a Joint Declaration agreeing that salvation is by grace alone, through faith, and that good works are the fruit of that faith. Both sides agree works cannot earn salvation, and both agree that real faith produces good works. I therefore conclude the statement is correct that works cannot earn salvation, but misleading if it implies works don't matter — true faith, as James says, is always shown in action.","evidence":["Ephesians 2:8–9","Romans 1:17","Romans 3:23","Luke 23:43","James 2:17, 24","Matthew 25:31–46","Council of Trent","Joint Declaration on the Doctrine of Justification (1999)"],"examTip":"The Catholic–Lutheran Joint Declaration is a great contemporary example for a balanced conclusion.","answerTopic":"faith vs works"},{"id":"aqa-rs-a-christianity-paper1-1-8-9","paper":"Beliefs","module":"1.8","moduleTitle":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","question":"‘God's grace is more important than following God's law.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nChristians believe no one can keep God's law perfectly — 'all have sinned and fall short of the glory of God' (Romans 3:23). If salvation depended on obeying the law, no one would be saved. Grace, God's free gift, is the only way: 'it is by grace you have been saved' (Ephesians 2:8).\n\nPaul argues that the law shows people their sin but cannot save them; 'a person is not justified by the works of the law, but by faith in Jesus Christ' (Galatians 2:16). Jesus himself criticised Pharisees who followed the law strictly but lacked love and mercy (Matthew 23:23). Grace is what changes the heart, which then makes people want to do good.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nJesus said 'Do not think that I have come to abolish the Law… but to fulfil' it (Matthew 5:17) and told the rich young man to 'keep the commandments' (Matthew 19:17). God's law, such as the Ten Commandments, still matters for Christians because it shows how to love God and neighbour.\n\nGrace without obedience could become an excuse for bad behaviour. Paul himself asked, 'Shall we go on sinning so that grace may increase? By no means!' (Romans 6:1–2). Dietrich Bonhoeffer warned against 'cheap grace' — forgiveness without repentance or discipleship. Catholics stress that faith must be lived out in keeping the commandments and doing good works (James 2:17).\n\nThe law also has a social value: it underpins justice and protects the vulnerable, which Christians support through campaigning and charity.\n\nJUSTIFIED CONCLUSION\n\nBoth are important, but they are not equal in role. Grace is the source of salvation and comes first: God loves and forgives people before they obey him. The law then shows how those who have received grace should live, and the Spirit helps them to keep it. Bonhoeffer's warning about 'cheap grace' shows they cannot be separated. I conclude that grace is more important because salvation depends on it, but a Christian who ignored God's law would show that they had not really understood grace.","evidence":["Romans 3:23","Ephesians 2:8","Galatians 2:16","Matthew 23:23","Matthew 5:17","Matthew 19:17","Romans 6:1–2","Dietrich Bonhoeffer, The Cost of Discipleship ('cheap grace')"],"examTip":"Bonhoeffer's 'cheap grace' is a memorable evaluative point.","answerTopic":"grace vs law"},{"id":"aqa-rs-a-christianity-paper1-1-9-0","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Which one of the following best describes the Christian idea of atonement?\nA  Jesus' return at the end of time\nB  Restoring the relationship between God and humanity through Jesus' death\nC  Being baptised as a believer\nD  Jesus' birth in Bethlehem","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Restoring the relationship between God and humanity through Jesus' death\n\nAtonement literally means 'at-one-ment' — making God and humanity 'at one' again. Christians believe Jesus' death and resurrection repaired the relationship broken by sin. A is the Second Coming; C is believers' baptism; D is the nativity.","evidence":["Romans 5:10–11","2 Corinthians 5:18–19"],"examTip":"Remember the 'at-one-ment' breakdown to define atonement quickly.","answerTopic":"atonement"},{"id":"aqa-rs-a-christianity-paper1-1-9-1","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Which one of the following New Testament verses records Jesus saying he came 'to give his life as a ransom for many'?\nA  John 3:16\nB  Mark 10:45\nC  Romans 3:23\nD  Genesis 3:15","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Mark 10:45\n\nMark 10:45: 'For even the Son of Man did not come to be served, but to serve, and to give his life as a ransom for many.' This verse is the basis of the 'ransom' understanding of the atonement. (Genesis 3:15 is in the Old Testament.)","evidence":["Mark 10:45"],"examTip":"Mark 10:45 is one of the most useful quotations for this topic.","answerTopic":"ransom"},{"id":"aqa-rs-a-christianity-paper1-1-9-2","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Give one way Christians describe what Jesus' death achieved.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: it paid the price/ransom for sin; Jesus took the punishment humans deserved (substitution); it was the perfect sacrifice for sin; it defeated sin, death and evil (Christus Victor); it reconciled humans with God; it showed God's love and inspires people to change (moral example).","evidence":["Mark 10:45","1 Peter 2:24","Romans 5:8"],"examTip":"A key word like 'sacrifice', 'ransom' or 'reconciliation' is enough.","answerTopic":"meaning of Jesus' death"},{"id":"aqa-rs-a-christianity-paper1-1-9-3","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Give one Bible quotation that shows Jesus' death was a sacrifice for sin.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.:\n• 'Christ died for our sins according to the Scriptures' (1 Corinthians 15:3).\n• 'He himself bore our sins in his body on the cross' (1 Peter 2:24).\n• 'Look, the Lamb of God, who takes away the sin of the world!' (John 1:29).\n• 'to give his life as a ransom for many' (Mark 10:45).","evidence":["1 Corinthians 15:3","1 Peter 2:24","John 1:29","Mark 10:45"],"examTip":"Learn two or three short verses word-for-word.","answerTopic":"sacrifice"},{"id":"aqa-rs-a-christianity-paper1-1-9-4","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Explain two ways in which belief in the atonement influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe Jesus' death has reconciled them to God, so they feel forgiven and have confidence to approach God in prayer. This influences them to take part in services of Holy Communion, where they remember Jesus' sacrifice — 'This is my body given for you' (Luke 22:19) — and give thanks.\n\nSecond way: Because Christians believe Jesus gave his life for them, they try to live sacrificially for others, putting others' needs before their own. Paul writes that God 'gave us the ministry of reconciliation' (2 Corinthians 5:18), so Christians also work to reconcile people — for example by mediating in conflicts or supporting organisations like the Corrymeela Community.","evidence":["Luke 22:19","2 Corinthians 5:18","Corrymeela Community"],"examTip":"Using the Eucharist as an example links Beliefs to Practices — examiners like that.","answerTopic":"atonement influence"},{"id":"aqa-rs-a-christianity-paper1-1-9-5","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Explain two ways in which belief that Jesus is the Saviour influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Because Christians believe Jesus saves them from sin and death, they put their trust in him and follow him as Lord. Many describe making a personal commitment to Jesus, and they show this through regular worship, prayer and Bible reading.\n\nSecond way: Believing that salvation comes through Jesus — 'there is no other name under heaven… by which we must be saved' (Acts 4:12) — motivates many Christians to share the good news with others through evangelism, for example by running Alpha courses or supporting missionaries, so that others can be saved too.","evidence":["Acts 4:12","John 14:6","Alpha course"],"examTip":"Show how belief changes action.","answerTopic":"Saviour influence"},{"id":"aqa-rs-a-christianity-paper1-1-9-6","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Explain two Christian teachings about the role of Christ in salvation.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Jesus' death was a sacrifice that took away the sin of the world. John the Baptist calls Jesus 'the Lamb of God, who takes away the sin of the world' (John 1:29), linking him to the lambs sacrificed in the Temple and at Passover. Many Christians, especially evangelicals, believe in substitutionary atonement: Jesus took the punishment humans deserved — 'He himself bore our sins in his body on the cross' (1 Peter 2:24).\n\nSecond teaching: Through his resurrection Jesus defeated sin, death and evil, opening the way to eternal life. Paul writes 'Death has been swallowed up in victory' (1 Corinthians 15:54). This 'Christus Victor' view is especially emphasised by Orthodox Christians, whose Easter hymn proclaims Christ 'trampling down death by death'.\n\nApplication: Both teachings show Christians that salvation is achieved by Christ, not by human effort, and that his life, death and resurrection together reconcile people to God (Romans 5:10–11).","evidence":["John 1:29","1 Peter 2:24","1 Corinthians 15:54–57","Romans 5:10–11","Orthodox Paschal troparion"],"examTip":"Name different theories of atonement to show breadth.","answerTopic":"Christ's role in salvation"},{"id":"aqa-rs-a-christianity-paper1-1-9-7","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"Explain two different Christian understandings of the atonement.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First understanding — substitution/sacrifice: Jesus died in the place of sinners, taking the punishment for sin that humans deserved, so that God's justice is satisfied and people are forgiven. Isaiah 53:5, which Christians apply to Jesus, says 'he was pierced for our transgressions… the punishment that brought us peace was on him'. Anselm of Canterbury (11th century) argued that only one who was both God and human could pay the debt of human sin.\n\nSecond understanding — moral example/reconciliation through love: Jesus' death shows the depth of God's love and inspires people to turn back to God. 'God demonstrates his own love for us in this: while we were still sinners, Christ died for us' (Romans 5:8). This view, associated with Peter Abelard, stresses that the cross changes human hearts rather than changing God.\n\nApplication: Many Christians combine these ideas with the 'ransom' teaching in Mark 10:45 and with Christus Victor (Jesus defeating evil), believing no single picture captures the full meaning of the cross.","evidence":["Isaiah 53:5","Romans 5:8","Mark 10:45","Anselm, Cur Deus Homo","Peter Abelard"],"examTip":"If you name a theologian, also explain the idea in your own words.","answerTopic":"atonement theories"},{"id":"aqa-rs-a-christianity-paper1-1-9-8","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"‘Jesus' death was the only way for humans to be saved.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nMany Christians believe sin creates a separation from God that humans cannot repair themselves, since 'the wages of sin is death' (Romans 6:23). A perfect sacrifice was needed, and only Jesus, who is both God and sinless human, could offer it. Anselm argued that humanity owed a debt only humanity should pay but only God could pay — so the God-man had to die.\n\nJesus himself said 'I am the way and the truth and the life. No one comes to the Father except through me' (John 14:6), and Peter declared 'there is no other name under heaven… by which we must be saved' (Acts 4:12). In Gethsemane Jesus prayed 'if it is possible, may this cup be taken from me' (Matthew 26:39); some Christians argue that because he still had to die, there was no other way. Many evangelical Protestants hold this view firmly.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nSome Christians argue that an omnipotent, loving God could have forgiven humanity without anyone dying. In the Parable of the Lost Son (Luke 15) the father forgives freely without demanding payment. On this view the cross was the way God chose to show his love (Romans 5:8), rather than the only possible way.\n\nOthers stress that salvation involves Jesus' whole life, resurrection and the work of the Spirit, not his death alone. Paul says 'if Christ has not been raised… you are still in your sins' (1 Corinthians 15:17), so the resurrection is equally essential. Catholics and Orthodox also teach that salvation is received through the sacraments and a life of faith.\n\nSome liberal Christians and people of other faiths argue that God may save people of good will who have never heard of Jesus. The Catholic Church teaches that those who, through no fault of their own, do not know Christ but seek God sincerely may still be saved (Catechism 847) — though even then it is through Christ's grace.\n\nJUSTIFIED CONCLUSION\n\nChristian teaching is clear that salvation comes through Christ, and his death is at the centre of that. However, the statement says his death was 'the only way', and it is less clear that God could not have chosen another method; many theologians see the cross as the fitting and most loving way rather than a necessity. Also, salvation includes the resurrection, not death alone. I conclude that for Christians salvation comes only through Jesus, but it is better to say his death and resurrection together are God's chosen way of saving humanity than that his death was the only possible way.","evidence":["Romans 6:23","John 14:6","Acts 4:12","Matthew 26:39","Luke 15:11–32","Romans 5:8","1 Corinthians 15:17","Anselm","Catechism 847"],"examTip":"Unpick key phrases — 'death' and 'only' — to reach a precise judgement.","answerTopic":"necessity of the cross"},{"id":"aqa-rs-a-christianity-paper1-1-9-9","paper":"Beliefs","module":"1.9","moduleTitle":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","question":"‘The idea of atonement has no relevance for Christians today.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nThe language of atonement — sacrifice, ransom, blood, paying a debt — comes from ancient Jewish Temple practice and medieval ideas of honour, which can seem strange today. Many people in modern Britain do not think in terms of sin needing to be paid for, so the idea may seem outdated or even troubling. Some critics argue that a God who requires the death of his Son to forgive seems harsh.\n\nSome Christians focus mainly on Jesus' moral teaching — love, justice and compassion — and consider his example more relevant to modern life than theories about how his death saves people. Non-religious people would say the idea has no relevance because they reject the existence of sin and God altogether.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nFor most Christians, atonement is at the heart of their faith. 'Christ died for our sins' (1 Corinthians 15:3) is part of what Paul calls the gospel 'of first importance'. Christians remember it every time they share Holy Communion — 'This is my blood of the covenant, which is poured out for many for the forgiveness of sins' (Matthew 26:28) — and every Good Friday.\n\nThe idea is personally relevant because it offers forgiveness and freedom from guilt. Many Christians testify that knowing they are forgiven has transformed their lives, for example people who have turned away from addiction or crime.\n\nAtonement also has social relevance. Paul says God 'reconciled us to himself through Christ and gave us the ministry of reconciliation' (2 Corinthians 5:18). Christians work for reconciliation between communities — for example Coventry Cathedral's Community of the Cross of Nails, founded after the bombing of 1940 — inspired by the reconciling power of the cross.\n\nJUSTIFIED CONCLUSION\n\nThe older language of atonement may need explaining, and some theories are disputed even among Christians. However, the core idea — that through Jesus people can be reconciled to God and to each other — is clearly relevant to Christians today, both personally and socially. Its continuing place in worship and in reconciliation work shows it is far from irrelevant. I therefore disagree strongly with the statement, though I accept it may seem irrelevant from a non-religious point of view.","evidence":["1 Corinthians 15:3","Matthew 26:28","2 Corinthians 5:18–19","Community of the Cross of Nails (Coventry Cathedral)"],"examTip":"Relevance questions are best answered with contemporary examples.","answerTopic":"relevance of atonement"}],"paper2":[{"id":"aqa-rs-a-christianity-paper2-2-1-0","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Which one of the following is an example of liturgical worship?\nA  A Quaker meeting held mostly in silence\nB  A Catholic Mass\nC  A spontaneous prayer at home\nD  A house group Bible study","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — A Catholic Mass\n\nLiturgical worship follows a set order of service with set words and rituals, often from a service book. The Catholic Mass follows a fixed structure (Liturgy of the Word, Liturgy of the Eucharist). Quaker meetings are informal/unprogrammed; spontaneous prayer and house groups are informal or non-liturgical.","evidence":["Roman Missal","Book of Common Prayer / Common Worship"],"examTip":"Know one clear example of each type of worship.","answerTopic":"liturgical worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-1","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Which one of the following Christian groups is best known for worship based on silent waiting on God?\nA  Pentecostals\nB  The Orthodox Church\nC  The Religious Society of Friends (Quakers)\nD  Roman Catholics","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C — The Religious Society of Friends (Quakers)\n\nQuakers meet in silence, without clergy or a set liturgy; anyone may stand and speak (minister) if they feel moved by the Spirit. Pentecostal worship is lively and spontaneous; Orthodox and Catholic worship are highly liturgical.","evidence":["Quaker Faith \u0026 Practice"],"examTip":"Quakers are the classic example of informal worship.","answerTopic":"Quaker worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-2","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Give one feature of non-liturgical worship.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: no fixed order of service / set words; centred on Bible readings and a sermon; spontaneous or extempore prayers led by a minister; hymns and modern worship songs chosen by the leader; often found in Baptist, Methodist or evangelical churches; may include personal testimonies.","evidence":["Non-liturgical worship"],"examTip":"Any accurate feature earns the mark.","answerTopic":"non-liturgical worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-3","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Give one way in which the Bible is used in Christian worship.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: readings from the Old and New Testaments during services; the Gospel is read (often with people standing) in liturgical services; sermons explain a Bible passage; psalms are sung or said; prayers and hymns use biblical words; private Bible reading or study in house groups.","evidence":["2 Timothy 3:16","Psalms"],"examTip":"Keep it to one clear use.","answerTopic":"Bible in worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-4","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Explain two different ways in which Christians worship.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way — liturgical worship: Catholic, Orthodox and Anglican Christians often worship using a set liturgy with fixed prayers, readings and actions, such as the Mass or Divine Liturgy. The familiar structure lets the whole congregation take part together and links them to Christians worldwide and through history.\n\nSecond way — informal worship: Some Christians worship in a spontaneous, unstructured way. In a Pentecostal service, worshippers may raise their hands, sing modern songs, pray aloud and speak in tongues as they feel led by the Holy Spirit; Quakers by contrast sit in silence until someone feels moved to speak. These show that worship can be a free response to God.","evidence":["Catholic Mass","Pentecostal worship","Quaker meeting","Acts 2"],"examTip":"For 'different ways', choose two genuinely contrasting forms and say who uses them.","answerTopic":"forms of worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-5","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Explain two ways in which private worship is important for Christians.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Private worship allows Christians to build a personal relationship with God. Jesus taught 'when you pray, go into your room, close the door and pray to your Father, who is unseen' (Matthew 6:6). Daily personal prayer helps Christians to talk honestly to God about their worries and thanks.\n\nSecond way: Private worship such as Bible reading, meditation or using devotional aids (e.g. a rosary for Catholics or an icon for Orthodox Christians) helps Christians to grow spiritually and to apply their faith to everyday life. It means they can worship anywhere and at any time — for example housebound people who cannot attend church.","evidence":["Matthew 6:6","Rosary","Icons"],"examTip":"Mention a practical example of private worship.","answerTopic":"private worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-6","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Explain two reasons why liturgical worship is important for many Christians.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First reason: Liturgical worship links Christians to tradition and to the worldwide Church. The words of the Mass or the Anglican Common Worship have been used for centuries, many based on scripture — for example, the words of institution at the Last Supper, 'Do this in remembrance of me' (Luke 22:19). Worshippers feel united with Christians across the world and throughout history.\n\nSecond reason: A set structure helps people to worship fully without distraction, and ensures the whole of the faith is covered. Liturgy usually includes confession, Bible readings, the creed, intercession and Holy Communion, following the pattern of the early Church, which 'devoted themselves to the apostles' teaching and to fellowship, to the breaking of bread and to prayer' (Acts 2:42). Familiar words, such as the Lord's Prayer, mean everyone, including children and those with dementia, can join in.\n\nApplication: Catholic teaching describes the liturgy, especially the Eucharist, as 'the source and summit of the Christian life' (Catechism 1324).","evidence":["Luke 22:19","Acts 2:42","Catechism 1324","Common Worship"],"examTip":"Acts 2:42 is a useful source for any question on Christian worship.","answerTopic":"importance of liturgy"},{"id":"aqa-rs-a-christianity-paper2-2-1-7","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"Explain two ways in which Christians use the Bible in worship.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: The Bible is read aloud in public worship. Most services include readings from the Old Testament, a psalm, a New Testament letter and a Gospel. In Catholic, Orthodox and Anglican churches the Gospel is treated with special honour — people stand and it may be carried in procession — because it contains the words of Jesus. Christians believe 'All Scripture is God-breathed and is useful for teaching' (2 Timothy 3:16).\n\nSecond way: The Bible is explained in sermons and used in private and group study. In non-liturgical churches such as Baptist or evangelical churches, the sermon based on a Bible passage is often the central part of the service. Christians may also read the Bible daily or join house groups, following the Bereans who 'examined the Scriptures every day' (Acts 17:11).\n\nApplication: Many hymns and prayers also use biblical words — for example the Lord's Prayer (Matthew 6:9–13) and the psalms — so the Bible shapes all forms of Christian worship.","evidence":["2 Timothy 3:16","Acts 17:11","Matthew 6:9–13","Psalms"],"examTip":"Show contrast between traditions (e.g. Gospel procession vs central sermon).","answerTopic":"Bible in worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-8","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"‘Informal worship is the best way for Christians to worship God.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nInformal worship allows Christians to respond freely to God's Spirit. Jesus said true worshippers 'will worship the Father in the Spirit and in truth' (John 4:23), not in a particular place or form. In Pentecostal and charismatic churches people pray aloud, sing, dance and use spiritual gifts, as at Pentecost (Acts 2), which many find deeply meaningful.\n\nInformal worship can be more personal and relevant. Spontaneous prayers can address real concerns, and modern music and language appeal to young people and newcomers. Messy Church and many fast-growing churches use informal styles to reach people who find traditional services off-putting. Quaker silent worship shows that formality is not needed to sense God's presence.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nLiturgical worship has deep roots in scripture and tradition. The early Church 'devoted themselves to the apostles' teaching… to the breaking of bread and to prayer' (Acts 2:42), and Jesus commanded 'do this in remembrance of me' (Luke 22:19). Catholics, Orthodox and many Anglicans believe the Eucharistic liturgy is the 'source and summit' of Christian life — more central than any informal style.\n\nSet liturgy unites Christians across the world and protects the content of worship: confession, the creed and scripture readings are always included. Informal worship can depend too much on the leader, or become focused on emotion and entertainment. Familiar prayers also make it easier for everyone — children, elderly or those with disabilities — to participate.\n\nMany Christians would add that private worship and non-liturgical services centred on the Bible are equally valid; no single form is 'best'.\n\nJUSTIFIED CONCLUSION\n\nInformal worship has real strengths in freedom, relevance and openness to the Spirit. But the statement claims it is the 'best' way for Christians in general, and this ignores the strong scriptural and historical case for liturgy and the fact that different Christians are helped by different styles. Since Jesus emphasised worship 'in the Spirit and in truth' rather than any particular form, I conclude that the best worship is whatever sincerely draws a Christian closer to God — for some that will be informal, for others liturgical — so the statement is too sweeping.","evidence":["John 4:23–24","Acts 2","Acts 2:42","Luke 22:19","Catechism 1324","Messy Church","Quaker meeting"],"examTip":"Give named examples of each form of worship (e.g. Pentecostal, Quaker, Catholic Mass).","answerTopic":"best form of worship"},{"id":"aqa-rs-a-christianity-paper2-2-1-9","paper":"Practices","module":"2.1","moduleTitle":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","question":"‘Private worship is more important than worshipping with others.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nJesus warned against praying to be seen by others and told his followers to 'go into your room, close the door and pray to your Father, who is unseen' (Matthew 6:5–6). Private worship is where Christians develop an honest, personal relationship with God. Jesus himself often withdrew to pray alone (Luke 5:16).\n\nPrivate prayer and Bible reading can be done every day, at any time, wherever a person is, while public worship might be only weekly. For those who are ill, housebound or living where Christians are persecuted, private worship may be the only possibility. Many Christians believe a real faith depends on daily personal devotion rather than attendance at services.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nChristianity is a community faith. Hebrews says 'not giving up meeting together… but encouraging one another' (Hebrews 10:25), and Jesus promised 'where two or three gather in my name, there am I with them' (Matthew 18:20). The Church is described as the 'body of Christ' (1 Corinthians 12:27), so worshipping together is essential.\n\nSome acts of worship can only happen with others. Catholics have a duty to attend Mass on Sundays and holy days, and the sacraments, especially Holy Communion, are celebrated by the community. Corporate worship also provides teaching through sermons, support in difficult times and the opportunity to serve others.\n\nWorshipping together also gives a public witness to faith and builds the fellowship described in Acts 2:42–47.\n\nJUSTIFIED CONCLUSION\n\nBoth forms are necessary, and Jesus himself practised both — praying alone and joining in synagogue worship and the Last Supper with his disciples. Private worship is vital for a personal relationship with God, but Christian teaching about the body of Christ and the sacraments means that worship with others cannot be replaced. I conclude that private worship is not more important: the two support each other, but for most Christians, especially Catholics and Orthodox, communal worship is at the centre because it is where the sacraments are celebrated.","evidence":["Matthew 6:5–6","Luke 5:16","Hebrews 10:25","Matthew 18:20","1 Corinthians 12:27","Acts 2:42–47"],"examTip":"Note different denominational emphases (e.g. Catholic Sunday obligation).","answerTopic":"private vs public worship"},{"id":"aqa-rs-a-christianity-paper2-2-2-0","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"In which Gospel passage does Jesus teach the Lord's Prayer as part of the Sermon on the Mount?\nA  Matthew 6\nB  Mark 16\nC  John 3\nD  Luke 2","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A — Matthew 6\n\nJesus teaches the Lord's Prayer in Matthew 6:9–13 during the Sermon on the Mount. A shorter version is in Luke 11:2–4, where the disciples ask 'Lord, teach us to pray'.","evidence":["Matthew 6:9–13","Luke 11:1–4"],"examTip":"Know both locations of the Lord's Prayer.","answerTopic":"Lord's Prayer source"},{"id":"aqa-rs-a-christianity-paper2-2-2-1","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"Which one of the following is a set prayer?\nA  A prayer made up on the spot in a house group\nB  The Hail Mary\nC  A silent personal conversation with God\nD  A spontaneous prayer for a sick friend","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — The Hail Mary\n\nA set prayer has fixed words that are used repeatedly. The Hail Mary is a traditional set prayer, especially used by Catholics, often with a rosary. The other options are informal (extempore) prayers.","evidence":["Hail Mary (based on Luke 1:28, 42)"],"examTip":"Set = fixed words; informal = own words.","answerTopic":"set prayer"},{"id":"aqa-rs-a-christianity-paper2-2-2-2","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"Give one type of prayer.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: adoration (praise); confession; thanksgiving; supplication/petition (asking for oneself); intercession (praying for others); set/formal prayer; informal/extempore prayer; meditation/contemplation. (ACTS = Adoration, Confession, Thanksgiving, Supplication.)","evidence":["ACTS model"],"examTip":"The ACTS acronym gives four quick answers.","answerTopic":"types of prayer"},{"id":"aqa-rs-a-christianity-paper2-2-2-3","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"Give one phrase from the Lord's Prayer.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: 'Our Father in heaven / who art in heaven'; 'hallowed be your name'; 'your kingdom come'; 'your will be done, on earth as in heaven'; 'give us today our daily bread'; 'forgive us our sins/trespasses as we forgive those who sin against us'; 'lead us not into temptation'; 'deliver us from evil'.","evidence":["Matthew 6:9–13"],"examTip":"Accept traditional or modern wording.","answerTopic":"Lord's Prayer phrases"},{"id":"aqa-rs-a-christianity-paper2-2-2-4","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"Explain two different ways in which Christians pray.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way — set prayers: Many Christians, especially Catholic, Orthodox and Anglican, use set prayers with fixed words such as the Lord's Prayer, the Hail Mary or the Jesus Prayer ('Lord Jesus Christ, Son of God, have mercy on me'). These are said together in services or privately, and are helpful when people can't find their own words.\n\nSecond way — informal prayer: Other Christians, particularly in evangelical and Pentecostal churches, pray in their own words, speaking to God spontaneously like talking to a friend. This may happen aloud in a prayer meeting or silently at any time of day, allowing them to express personal feelings and specific needs.","evidence":["Matthew 6:9–13","Jesus Prayer","Hail Mary"],"examTip":"Contrast set and informal prayer, giving examples of each.","answerTopic":"ways of praying"},{"id":"aqa-rs-a-christianity-paper2-2-2-5","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"Explain two ways in which the Lord's Prayer influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: The Lord's Prayer teaches Christians to forgive — 'forgive us our sins as we forgive those who sin against us'. Saying it regularly reminds them that they must forgive others if they want God's forgiveness, influencing how they deal with arguments and hurt.\n\nSecond way: The prayer asks 'your kingdom come, your will be done, on earth as in heaven'. This encourages Christians to work to make the world more like God's kingdom — just, peaceful and caring — for example by supporting food banks or campaigning against poverty. It also unites Christians of all denominations, since almost every church uses it.","evidence":["Matthew 6:9–13","Matthew 6:14–15"],"examTip":"Pick specific phrases and show how each one shapes behaviour.","answerTopic":"Lord's Prayer influence"},{"id":"aqa-rs-a-christianity-paper2-2-2-6","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"Explain two reasons why the Lord's Prayer is important to Christians.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First reason: It was given by Jesus himself. When the disciples asked 'Lord, teach us to pray' (Luke 11:1), Jesus gave them this prayer, and in Matthew 6:9 he said 'This, then, is how you should pray'. Christians believe it is the perfect model of prayer, so it is used in nearly every service, by all denominations, uniting Christians worldwide.\n\nSecond reason: It contains the key elements of Christian faith and prayer. It begins with praise ('hallowed be your name'), puts God's will first ('your kingdom come'), asks for daily needs ('our daily bread'), seeks forgiveness and commits to forgiving others, and asks for protection ('deliver us from evil'). The early theologian Tertullian called it 'a summary of the whole gospel'.\n\nApplication: Because it addresses God as 'Our Father', it reminds Christians that they belong to one family and can approach God with trust and love.","evidence":["Matthew 6:9–13","Luke 11:1–4","Tertullian, On Prayer"],"examTip":"Quote phrases from the prayer itself as your source.","answerTopic":"importance of Lord's Prayer"},{"id":"aqa-rs-a-christianity-paper2-2-2-7","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"Explain two Christian teachings about prayer.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Christians should pray sincerely and privately, not to impress others. Jesus said, 'when you pray, do not be like the hypocrites… go into your room, close the door and pray to your Father, who is unseen' (Matthew 6:5–6). Prayer is about a real relationship with God, not a performance.\n\nSecond teaching: Christians should pray constantly and with trust that God hears them. Paul writes, 'pray continually; give thanks in all circumstances' (1 Thessalonians 5:17–18), and Jesus said 'Ask and it will be given to you; seek and you will find' (Matthew 7:7). However, Christians believe God answers in his own way — even Jesus prayed in Gethsemane 'not as I will, but as you will' (Matthew 26:39).\n\nApplication: This explains why Christians pray daily — using set prayers, informal prayers or silent meditation — and continue praying even when prayers do not seem to be answered as they hoped.","evidence":["Matthew 6:5–6","1 Thessalonians 5:17–18","Matthew 7:7","Matthew 26:39"],"examTip":"Gethsemane is a powerful source for 'unanswered prayer'.","answerTopic":"teachings on prayer"},{"id":"aqa-rs-a-christianity-paper2-2-2-8","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"‘Set prayers are better than informal prayers.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nThe most important Christian prayer — the Lord's Prayer — is a set prayer, given by Jesus with the words 'This, then, is how you should pray' (Matthew 6:9). Set prayers carry the authority of scripture and tradition and have been tested over centuries, so they express Christian belief accurately.\n\nSet prayers unite Christians. When a congregation says the same words together, everyone takes part, and Christians across the world pray in the same way. They are especially helpful when people are stressed, grieving or unsure what to say; many Catholics find comfort in the rosary or the Hail Mary, and Orthodox Christians repeat the Jesus Prayer as a form of meditation.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nInformal prayer allows Christians to speak to God personally and honestly, like a child to a parent — Jesus taught them to call God 'Father'. It can address specific needs: a friend's illness, an exam, a world event. Many evangelical and Pentecostal Christians see spontaneous prayer as a sign of a living relationship with God and openness to the Spirit, who 'helps us in our weakness' when 'we do not know what we ought to pray for' (Romans 8:26).\n\nJesus warned against 'babbling like pagans' who think they will be heard 'because of their many words' (Matthew 6:7). Set prayers can become routine and be recited without thought. Quakers prefer silent waiting rather than set words.\n\nJesus himself prayed both ways: he used the psalms (a set prayer, Mark 15:34) and also prayed in his own words in Gethsemane.\n\nJUSTIFIED CONCLUSION\n\nBoth forms of prayer have strengths, and their weaknesses are opposite: set prayers can become automatic, while informal prayers can become self-centred or shallow. Since Jesus both taught a set prayer and prayed spontaneously, Christians generally see them as complementary. I conclude that set prayers are not 'better' in themselves; what matters is the sincerity of the person praying. Many Christians wisely use both — set prayers for structure and unity, informal prayers for personal relationship.","evidence":["Matthew 6:7–13","Romans 8:26","Mark 15:34 (Psalm 22)","Matthew 26:39","Rosary","Jesus Prayer"],"examTip":"Use Jesus' own practice as evidence for both sides.","answerTopic":"set vs informal prayer"},{"id":"aqa-rs-a-christianity-paper2-2-2-9","paper":"Practices","module":"2.2","moduleTitle":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","question":"‘Prayer is the most important part of a Christian's life.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nPrayer is how Christians communicate with God and build their relationship with him. Without prayer, faith can become just a set of ideas rather than a living relationship. Paul urges Christians to 'pray continually' (1 Thessalonians 5:17), suggesting prayer should run through every part of life.\n\nJesus made prayer central. He prayed before important decisions, often withdrew to pray alone (Luke 5:16), and taught his disciples the Lord's Prayer. In Gethsemane, facing death, he turned to prayer (Matthew 26:39). Many Christians, such as monks and nuns, dedicate their lives to prayer. Prayer also fuels everything else: Christians pray for guidance and strength before serving others.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nJesus said the greatest commandments are to love God and love your neighbour (Mark 12:30–31). Prayer is part of loving God, but loving and serving others is equally essential. James warns that faith without action is dead (James 2:17), and in the Parable of the Sheep and the Goats people are judged on whether they helped others, not on how much they prayed (Matthew 25:31–46).\n\nOther Christians would say the sacraments, especially Holy Communion, are the most important part of their life. Catholic teaching calls the Eucharist 'the source and summit of the Christian life'. Others would point to reading the Bible, or to faith in Jesus itself, as more fundamental.\n\nPrayer that does not lead to action could be hypocritical; Jesus criticised people who prayed publicly to be seen but neglected justice and mercy (Matthew 23:23).\n\nJUSTIFIED CONCLUSION\n\nPrayer is undeniably vital — it is the foundation of a Christian's relationship with God and was central to Jesus' own life. However, Christianity also requires love in action, sacraments and study of scripture, and these are not less important. I conclude that prayer is one of the most important parts of Christian life, but it is best seen not as separate from the rest; rather, prayer should inspire and be expressed through love for others, as the two great commandments show.","evidence":["1 Thessalonians 5:17","Luke 5:16","Matthew 26:39","Mark 12:30–31","James 2:17","Matthew 25:31–46","Matthew 23:23","Catechism 1324"],"examTip":"Compare prayer with at least two alternatives (e.g. service, sacraments).","answerTopic":"importance of prayer"},{"id":"aqa-rs-a-christianity-paper2-2-3-0","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"How many sacraments are recognised by the Catholic and Orthodox Churches?\nA  Two\nB  Five\nC  Seven\nD  Twelve","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C — Seven\n\nCatholic and Orthodox Churches recognise seven sacraments: baptism, confirmation (chrismation in the Orthodox Church), Eucharist, reconciliation (confession), anointing of the sick, marriage (matrimony) and holy orders (ordination). Most Protestant Churches recognise two — baptism and Holy Communion — because these were directly commanded by Jesus.","evidence":["Catechism 1113","Matthew 28:19","Luke 22:19"],"examTip":"Learn the number and names of the sacraments for both Catholic and Protestant traditions.","answerTopic":"number of sacraments"},{"id":"aqa-rs-a-christianity-paper2-2-3-1","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"Which one of the following Christian groups practises believers' baptism rather than infant baptism?\nA  Roman Catholics\nB  Baptists\nC  Orthodox Christians\nD  Anglicans","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Baptists\n\nBaptists (and many Pentecostal and evangelical churches) practise believers' baptism — baptising only those old enough to make a personal declaration of faith, usually by full immersion. Catholics, Orthodox and Anglicans baptise infants.","evidence":["Acts 2:38","Romans 6:3–4"],"examTip":"The name 'Baptist' comes from their distinctive view of baptism.","answerTopic":"believers' baptism"},{"id":"aqa-rs-a-christianity-paper2-2-3-2","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"Give one meaning of the word 'sacrament'.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: an outward, visible sign of an inward, invisible grace (Augustine / Book of Common Prayer); a religious ceremony through which Christians believe they receive God's grace; a sacred rite instituted by Christ.","evidence":["Augustine","Book of Common Prayer Catechism","Catechism of the Catholic Church 1131"],"examTip":"The classic definition — 'an outward sign of inward grace' — is worth memorising.","answerTopic":"meaning of sacrament"},{"id":"aqa-rs-a-christianity-paper2-2-3-3","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"Give one symbol used in baptism.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: water (cleansing from sin / new life); the sign of the cross; oil (chrism — strength, anointing by the Spirit); a lighted candle (Christ the light of the world); a white garment (purity, new life); immersion (dying and rising with Christ).","evidence":["Romans 6:4","John 8:12"],"examTip":"Name the symbol; a brief meaning is a bonus.","answerTopic":"baptism symbols"},{"id":"aqa-rs-a-christianity-paper2-2-3-4","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"Explain two different Christian beliefs about infant baptism.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First belief: Catholic, Orthodox, Anglican and Methodist Christians baptise babies. They believe baptism removes original sin and welcomes the child into God's family, so it should not be delayed. Parents and godparents make promises on the child's behalf, and the child later confirms their faith (e.g. at confirmation).\n\nSecond belief: Baptists, many Pentecostals and other evangelical Christians reject infant baptism. They argue that baptism should follow personal repentance and faith, as in Acts 2:38 ('Repent and be baptised'), which a baby cannot make. Instead, they may hold a service of dedication or thanksgiving for a baby, and baptise people as believers, usually by full immersion.","evidence":["Acts 2:38","Acts 16:33 (household baptism)","Catechism 1250"],"examTip":"'Different beliefs' questions need two genuinely contrasting views — name the denominations.","answerTopic":"infant baptism beliefs"},{"id":"aqa-rs-a-christianity-paper2-2-3-5","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"Explain two ways in which the sacrament of baptism is important for Christians.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Baptism is the way a person becomes a member of the Church. It is a rite of initiation into the Christian community, followed in obedience to Jesus' command to 'make disciples… baptising them in the name of the Father and of the Son and of the Holy Spirit' (Matthew 28:19). The community promises to support the newly baptised.\n\nSecond way: Baptism symbolises cleansing from sin and new life in Christ. Going under the water represents dying to an old life and rising with Christ (Romans 6:4). For many Christians it is a public declaration of faith that marks a turning point in their lives.","evidence":["Matthew 28:19","Romans 6:3–4","Mark 1:9–11"],"examTip":"Develop each point with what it means or what happens.","answerTopic":"importance of baptism"},{"id":"aqa-rs-a-christianity-paper2-2-3-6","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"Explain two Christian teachings about the sacrament of baptism.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First teaching: Baptism was commanded by Jesus and follows his own example. Jesus was baptised by John in the River Jordan, when the Spirit descended and the Father's voice was heard (Mark 1:9–11). Before ascending, he instructed the disciples to baptise 'in the name of the Father and of the Son and of the Holy Spirit' (Matthew 28:19), which is why all Christian baptisms use this Trinitarian formula.\n\nSecond teaching: Baptism unites a person with Christ's death and resurrection and gives new life. Paul writes 'We were therefore buried with him through baptism into death in order that, just as Christ was raised from the dead… we too may live a new life' (Romans 6:4). Catholic teaching states baptism removes original sin and makes the person a child of God and member of the Church (Catechism 1213).\n\nApplication: These teachings explain why water and immersion are used, and why Christians see baptism as the beginning of the Christian life.","evidence":["Mark 1:9–11","Matthew 28:19","Romans 6:3–4","Catechism 1213"],"examTip":"Combine a Gospel source with Paul's explanation in Romans 6.","answerTopic":"baptism teachings"},{"id":"aqa-rs-a-christianity-paper2-2-3-7","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"Explain two differences between infant baptism and believers' baptism.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First difference — who is baptised and why: In infant baptism (Catholic, Orthodox, Anglican), babies are baptised because the Church teaches baptism cleanses original sin and brings God's grace as a gift that does not depend on the child's understanding. Supporters point to households being baptised in Acts (Acts 16:33). In believers' baptism (Baptist, many Pentecostal churches), only those old enough to repent and believe are baptised, following Peter's words 'Repent and be baptised' (Acts 2:38).\n\nSecond difference — how it is done: Infant baptism usually takes place at a font. The priest pours water three times over the baby's head, makes the sign of the cross, and may anoint with oil; parents and godparents make promises and a candle is lit. Believers' baptism is usually by full immersion in a baptistery pool or river; the person gives a personal testimony and goes fully under the water, symbolising being 'buried with him' and rising to new life (Romans 6:4).\n\nApplication: Both use water and the Trinitarian formula of Matthew 28:19.","evidence":["Acts 16:33","Acts 2:38","Romans 6:4","Matthew 28:19"],"examTip":"A 'difference' answer should compare both sides in each point.","answerTopic":"infant vs believers' baptism"},{"id":"aqa-rs-a-christianity-paper2-2-3-8","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"‘Babies should not be baptised.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nBaptists and many Pentecostal and evangelical Christians argue that baptism should be a free personal choice to follow Jesus. In the New Testament, baptism follows repentance and faith: 'Repent and be baptised, every one of you' (Acts 2:38); the Ethiopian official was baptised after declaring his belief (Acts 8:36–38). A baby cannot repent or believe, so they argue infant baptism is not biblical.\n\nJesus himself was baptised as an adult (Mark 1:9), and believers' baptism by full immersion clearly shows dying and rising with Christ (Romans 6:4). Baptising babies may produce nominal Christians who were 'christened' but never come to personal faith. Many such churches instead hold a dedication service for babies, giving thanks and praying for them, while leaving baptism until they can decide.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nCatholic, Orthodox, Anglican, Methodist and other churches baptise infants. They teach that baptism is a sacrament of God's grace, a gift that does not depend on human understanding or effort. Since every person is born with original sin, baptism cleanses the child and welcomes them into God's family from the start of life (Catechism 1250).\n\nThere is biblical support: whole households were baptised (Acts 16:33), which probably included children; Peter said the promise 'is for you and your children' (Acts 2:39); and Jesus said 'Let the little children come to me… for the kingdom of God belongs to such as these' (Mark 10:14). Baptism in the New Testament also replaced circumcision, which was given to Jewish baby boys (Colossians 2:11–12).\n\nThe child is not left without choice: parents and godparents promise to bring them up in the faith, and later the child can confirm those promises for themselves at confirmation.\n\nJUSTIFIED CONCLUSION\n\nBoth sides take scripture seriously, and the disagreement depends on what baptism is understood to be. If it is mainly a personal declaration of faith, believers' baptism makes more sense. If it is mainly God's gift of grace, then infants need not wait. Because the New Testament describes household baptisms, and because most Christians understand baptism as God's action rather than ours, I disagree with the statement — though I accept that Baptist Christians have strong reasons for their view, and both traditions agree that personal commitment must follow.","evidence":["Acts 2:38–39","Acts 8:36–38","Acts 16:33","Mark 10:14","Romans 6:4","Colossians 2:11–12","Catechism 1250"],"examTip":"Show you understand the theological reason behind each practice, not just the practice.","answerTopic":"infant baptism debate"},{"id":"aqa-rs-a-christianity-paper2-2-3-9","paper":"Practices","module":"2.3","moduleTitle":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","question":"‘Sacraments are essential for Christians.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nJesus commanded the two main sacraments: baptism ('baptising them in the name of the Father and of the Son and of the Holy Spirit', Matthew 28:19) and Holy Communion ('do this in remembrance of me', Luke 22:19). Since they come from Jesus, Christians must practise them. Jesus also said 'no one can enter the kingdom of God unless they are born of water and the Spirit' (John 3:5), which many link to baptism.\n\nCatholic and Orthodox Christians believe the seven sacraments are channels of God's grace, given at key moments of life: baptism, confirmation, Eucharist, reconciliation, anointing of the sick, marriage and holy orders. The Catholic Church teaches that the sacraments are 'necessary for salvation' for believers (Catechism 1129) and that the Eucharist is 'the source and summit of the Christian life'. Sacraments make God's grace tangible through water, bread, wine and oil.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nQuakers and the Salvation Army do not celebrate outward sacraments at all. They believe the whole of life can be sacramental and that grace is received inwardly and directly from God; the Salvation Army also wanted to avoid alcohol and divisions over ritual. Their members clearly live committed Christian lives.\n\nMany Protestants believe salvation is by grace through faith (Ephesians 2:8–9), not through rituals. The criminal crucified beside Jesus was promised paradise without baptism or communion (Luke 23:43). For these Christians, sacraments are important signs and acts of obedience, but not essential for salvation.\n\nMost Protestants also recognise only two sacraments, so the claim that seven sacraments are essential is not shared by all.\n\nJUSTIFIED CONCLUSION\n\nFor Catholic and Orthodox Christians the statement is clearly true: sacraments are the ordinary means of grace given by Christ. For most Protestants they are important commands of Jesus but not essential to salvation, and for Quakers they are unnecessary in outward form. Given that Jesus commanded baptism and communion, I conclude that sacraments are essential to the life of the Church and should be practised by Christians, but the example of the thief on the cross shows they are not essential for salvation itself — God's grace is not limited to them.","evidence":["Matthew 28:19","Luke 22:19","John 3:5","Catechism 1129, 1324","Ephesians 2:8–9","Luke 23:43","Quakers / Salvation Army"],"examTip":"Quakers and the Salvation Army are excellent examples for the opposing view.","answerTopic":"importance of sacraments"},{"id":"aqa-rs-a-christianity-paper2-2-4-0","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Which one of the following is the Catholic belief that the bread and wine become the body and blood of Christ?\nA  Consubstantiation\nB  Transubstantiation\nC  Memorialism\nD  Incarnation","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — Transubstantiation\n\nTransubstantiation is the Catholic teaching that at the consecration the substance of the bread and wine is changed into the body and blood of Christ, although the appearance (accidents) remains. 'Consubstantiation' is a term often used for the Lutheran view that Christ is present 'in, with and under' the bread and wine; memorialism (e.g. Zwingli, many Baptists) sees the meal as a remembrance.","evidence":["Catechism 1376","Council of Trent"],"examTip":"Be precise with the spelling and meaning of transubstantiation.","answerTopic":"transubstantiation"},{"id":"aqa-rs-a-christianity-paper2-2-4-1","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Which one of the following events does Holy Communion remember?\nA  The Sermon on the Mount\nB  The Last Supper\nC  The feeding of the 5000\nD  The wedding at Cana","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B — The Last Supper\n\nHoly Communion re-enacts and remembers the Last Supper, Jesus' final meal with his disciples before his crucifixion, when he took bread and wine and said 'This is my body… This is my blood… do this in remembrance of me' (Luke 22:19–20; 1 Corinthians 11:23–26).","evidence":["Luke 22:19–20","1 Corinthians 11:23–26"],"examTip":"Link the sacrament to its origin in the Gospels.","answerTopic":"Last Supper"},{"id":"aqa-rs-a-christianity-paper2-2-4-2","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Give one name used by Christians for the sacrament of Holy Communion.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: the Eucharist (meaning 'thanksgiving'); the Mass (Catholic); the Lord's Supper; the Breaking of Bread; the Divine Liturgy (Orthodox name for the service); Holy Communion.","evidence":["1 Corinthians 11:20 'the Lord's Supper'","Acts 2:42 'the breaking of bread'"],"examTip":"Different names often reflect different denominations.","answerTopic":"names of Eucharist"},{"id":"aqa-rs-a-christianity-paper2-2-4-3","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Give one reason why some Christians receive Holy Communion every week or more often.","marks":1,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any one of, e.g.: Jesus commanded 'do this in remembrance of me'; they believe they receive Christ himself / God's grace; it strengthens their faith; Catholics have an obligation to attend Mass on Sundays; it unites them with the Church as the body of Christ; the early Church broke bread regularly (Acts 2:42, 46).","evidence":["Luke 22:19","Acts 2:42, 46","Catechism 2180"],"examTip":"Give one clear reason.","answerTopic":"frequency of communion"},{"id":"aqa-rs-a-christianity-paper2-2-4-4","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Explain two different ways in which Holy Communion is celebrated.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way — the Catholic Mass: A priest leads a formal liturgy including Bible readings and a homily, then consecrates the bread (unleavened wafers/hosts) and wine on the altar using Jesus' words. Catholics believe this makes present Christ's sacrifice, and they receive the host, sometimes also the cup. Mass is celebrated daily in many churches.\n\nSecond way — in many nonconformist churches (e.g. Baptist): The Lord's Supper may be held monthly as a simpler service. A minister reads the words of institution from 1 Corinthians 11, then ordinary bread and often non-alcoholic wine in small individual cups are passed around the seated congregation. It is understood mainly as a memorial and an act of fellowship.\n\n(Orthodox Christians celebrate the Divine Liturgy, receiving leavened bread soaked in wine from a spoon.)","evidence":["1 Corinthians 11:23–26","Catholic Mass","Baptist Lord's Supper","Orthodox Divine Liturgy"],"examTip":"Contrast leaders, frequency, elements and beliefs.","answerTopic":"ways of celebrating communion"},{"id":"aqa-rs-a-christianity-paper2-2-4-5","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Explain two ways in which receiving Holy Communion influences Christians today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First way: Christians believe they receive God's grace and spiritual strength through Communion. Many Catholics feel they receive Christ himself, which gives them the strength to live a Christian life during the week and to face difficulties with hope.\n\nSecond way: Communion unites believers as one community: 'Because there is one loaf, we, who are many, are one body' (1 Corinthians 10:17). This encourages Christians to be reconciled with others — many services include sharing the peace — and to serve others; some churches link Communion with collections for the poor or food bank donations. Catholics often end Mass with 'Go in peace, glorifying the Lord by your life'.","evidence":["1 Corinthians 10:17","John 6:35","Sign of peace"],"examTip":"Show influence on both the individual and the community.","answerTopic":"influence of communion"},{"id":"aqa-rs-a-christianity-paper2-2-4-6","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Explain two different Christian interpretations of the meaning of Holy Communion.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First interpretation — real presence: Catholics believe in transubstantiation: when the priest consecrates the bread and wine, they become the actual body and blood of Christ, though they still look and taste the same. This is based on Jesus' words 'This is my body' (Luke 22:19) and 'whoever eats my flesh and drinks my blood has eternal life' (John 6:54). Orthodox Christians also believe in a real change but call it a mystery; Lutherans believe Christ is truly present 'in, with and under' the bread and wine.\n\nSecond interpretation — memorial: Many Protestants, such as Baptists and some other nonconformist churches, believe the bread and wine are symbols that remind Christians of Jesus' sacrifice. They emphasise Jesus' command 'do this in remembrance of me' (1 Corinthians 11:24) and Paul's teaching that 'whenever you eat this bread and drink this cup, you proclaim the Lord's death until he comes' (1 Corinthians 11:26). This view goes back to the reformer Ulrich Zwingli.\n\nApplication: Anglicans hold a range of views between these positions. These differences affect how the bread and wine are treated after the service — Catholics reserve the consecrated hosts in a tabernacle.","evidence":["Luke 22:19","John 6:54","1 Corinthians 11:24–26","Catechism 1376","Ulrich Zwingli"],"examTip":"Name a denomination for each interpretation — the AQA spec stresses 'different interpretations'.","answerTopic":"meanings of communion"},{"id":"aqa-rs-a-christianity-paper2-2-4-7","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"Explain two reasons why Holy Communion is important for Christians.\n\nRefer to sacred writings or another source of Christian belief and teaching in your answer.","marks":6,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"First reason: It was instituted by Jesus at the Last Supper and he commanded it. 'He took bread, gave thanks and broke it, and gave it to them, saying, \"This is my body given for you; do this in remembrance of me\"' (Luke 22:19). By celebrating it, Christians obey Jesus and remember his death and resurrection.\n\nSecond reason: It brings Christians close to God and to each other. Catholics believe they truly receive Christ; the Catechism calls the Eucharist 'the source and summit of the Christian life' (Catechism 1324). Protestants believe it strengthens faith and brings them into fellowship with Christ. Paul teaches that sharing one loaf makes believers 'one body' (1 Corinthians 10:17), so it expresses the unity of the Church.\n\nApplication: That is why, for most Christians, Holy Communion is the central act of worship, and why disagreements about who may receive it (e.g. Catholic restrictions on non-Catholics) are taken so seriously.","evidence":["Luke 22:19–20","Catechism 1324","1 Corinthians 10:16–17"],"examTip":"Use the words of institution as your source and apply them.","answerTopic":"importance of communion"},{"id":"aqa-rs-a-christianity-paper2-2-4-8","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"‘Holy Communion is the most important sacrament for Christians.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nHoly Communion was instituted by Jesus himself at the Last Supper with the command 'do this in remembrance of me' (Luke 22:19). Unlike baptism, which happens once, it is received repeatedly throughout life, continually nourishing faith. Jesus said 'I am the bread of life' and 'whoever eats my flesh and drinks my blood has eternal life' (John 6:35, 54).\n\nFor Catholics it is central: the Catechism calls the Eucharist 'the source and summit of the Christian life' (1324), and they believe Christ is truly present through transubstantiation. Orthodox Christians similarly see the Divine Liturgy as the heart of their faith. It is the main act of worship in most denominations, expressing the unity of the Church as 'one body' (1 Corinthians 10:17).\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nMany Christians would argue that baptism is more important, because it is the 'gateway' to all other sacraments. Without baptism a person is not a member of the Church and, in Catholic practice, cannot receive Communion. Jesus said 'no one can enter the kingdom of God unless they are born of water and the Spirit' (John 3:5). Baptism removes original sin and marks the start of the Christian life.\n\nSome Protestants, such as Baptists, see Communion as a memorial rather than a means of receiving Christ, and may celebrate it only monthly; for them the preaching of the Word may be equally central. Quakers and the Salvation Army do not celebrate outward sacraments at all, believing Christ can be encountered without them.\n\nOther Christians might argue that different sacraments are most important at different moments — for example reconciliation for a person seeking forgiveness, or the anointing of the sick at the end of life.\n\nJUSTIFIED CONCLUSION\n\nBaptism has a strong claim because it comes first and is necessary for the others. However, Holy Communion is the sacrament Christians share most often, it was given by Jesus on the night before he died, and it is the centre of worship in most of the Christian world. I conclude that for the majority of Christians — Catholic, Orthodox and many Anglicans — Holy Communion is the most important sacrament for ongoing Christian life, although baptism is foundational and some Protestant traditions would not rank either above the Word of God.","evidence":["Luke 22:19","John 6:35, 54","John 3:5","1 Corinthians 10:17","Catechism 1324","Quakers / Salvation Army"],"examTip":"Compare Communion directly with baptism — the obvious rival.","answerTopic":"most important sacrament"},{"id":"aqa-rs-a-christianity-paper2-2-4-9","paper":"Practices","module":"2.4","moduleTitle":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","question":"‘The bread and wine at Holy Communion are only symbols.’\n\nEvaluate this statement.\nIn your answer you should:\n• refer to Christian teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS IN SUPPORT OF THE STATEMENT\n\nMany Protestants, including Baptists and some others in the nonconformist tradition, hold a memorialist view. Jesus said 'do this in remembrance of me' (1 Corinthians 11:24), suggesting the purpose is to remember. Paul says that eating the bread and drinking the cup 'proclaim the Lord's death until he comes' (1 Corinthians 11:26) — an act of witness.\n\nJesus often spoke in metaphors: 'I am the gate', 'I am the vine'. So 'This is my body' can be understood symbolically too. The reformer Ulrich Zwingli argued 'is' means 'signifies'. Also, the bread and wine clearly remain bread and wine physically — chemical tests would show no change — so many people find a literal change hard to accept.\n\nARGUMENTS FOR A DIFFERENT VIEW\n\nThe Catholic Church teaches transubstantiation: at consecration the substance of the bread and wine truly becomes Christ's body and blood, while the appearances remain (Catechism 1376). Jesus did not say 'this represents my body' but 'this is my body'. In John 6 many followers left because Jesus insisted 'my flesh is real food and my blood is real drink' (John 6:55); he did not soften his words.\n\nOrthodox Christians also believe in a real change, describing it as a holy mystery. Lutherans believe Christ is truly present 'in, with and under' the bread and wine, and many Anglicans speak of the 'real presence'. Paul warns that anyone who eats and drinks 'without discerning the body' brings judgement on themselves (1 Corinthians 11:29), suggesting more than a mere symbol.\n\nThe word 'only' is also challenged: even for symbolic views, the meal is a powerful act of fellowship and of receiving grace, not 'only' a sign.\n\nJUSTIFIED CONCLUSION\n\nThere is a genuine and long-standing disagreement. The memorialist view is consistent with Jesus' use of metaphor and with the command to remember, but the strong language of John 6 and 1 Corinthians 11 and the belief of the majority of the world's Christians (Catholic and Orthodox) suggest more than a symbol. I conclude that the statement is too strong: even many Protestants believe Christ is spiritually present in Communion, so describing the bread and wine as 'only symbols' fails to capture what most Christians believe is happening.","evidence":["Luke 22:19","John 6:53–55","1 Corinthians 11:24–29","Catechism 1376","Ulrich Zwingli","Lutheran 'real presence'"],"examTip":"The word 'only' in the statement is a good handle for your conclusion.","answerTopic":"symbol or real presence"}]},"notes":[{"id":"aqa-rs-a-christianity-paper1-1-1","paper":"Beliefs","module":"1.1","title":"The nature of God: omnipotent, loving and just, and the problem of evil and suffering","specFocus":"Spec: Key beliefs — the nature of God: God as omnipotent, loving and just, and the problem of evil and suffering.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Christians believe in one God whose nature is revealed in the Bible and above all in Jesus. Three qualities are named in the specification.\n\nOmnipotent (all-powerful)\n• God created the universe from nothing (ex nihilo) simply by speaking: 'Let there be light' (Genesis 1:3).\n• 'With God all things are possible' (Matthew 19:26). The Apostles' Creed calls God 'the Father almighty'.\n• Most Christians say omnipotence means God can do anything that is logically possible and consistent with his nature — he cannot, for example, do evil.\n\nLoving (benevolent)\n• 'God is love' (1 John 4:8). God's love is agape — selfless, unconditional love.\n• The supreme example is the sending of Jesus: 'For God so loved the world that he gave his one and only Son' (John 3:16).\n• Influence: Christians try to love others unconditionally (Mark 12:31 'Love your neighbour as yourself'), find comfort in prayer, and support charities.\n\nJust\n• God is fair and righteous; he judges people according to how they live (Matthew 25:31–46, the sheep and the goats).\n• God demands justice for the poor: 'let justice roll on like a river' (Amos 5:24); 'act justly and love mercy' (Micah 6:8).\n• God's justice is balanced by mercy — through Jesus, God forgives those who repent.\n• Influence: Christians campaign for fairness (e.g. Fairtrade, Christian Aid, Tearfund) and take moral responsibility.\n\nThe problem of evil and suffering\n• Moral evil: suffering caused by human choices (war, abuse, crime). Natural evil: suffering from natural causes (earthquakes, disease).\n• The 'inconsistent triad': if God is omnipotent and loving, why does evil exist? Some conclude God does not exist or is not as Christians describe him. This can lead believers to doubt.\n\nChristian responses\n• Free will: God gave humans freedom so that love could be genuine; misuse of freedom brought sin into the world (the Fall, Genesis 3). Augustine taught that evil is the result of the Fall, not God's creation.\n• Soul-making: Irenaeus, and later John Hick, argued suffering helps humans grow into the 'likeness' of God by developing compassion, courage and patience.\n• Job: a righteous man who suffers; God's answer (Job 38–42) is that his wisdom is beyond human understanding. Christians are called to trust.\n• God shares suffering: through Jesus' crucifixion God experienced pain; the resurrection promises it will end — 'He will wipe every tear from their eyes' (Revelation 21:4).\n• Practical response: prayer, and helping those who suffer (Good Samaritan, Luke 10:25–37).\n\nDiversity of views\n• Some Christians emphasise God's sovereignty (e.g. Calvinist traditions), others God's self-limiting love giving freedom to creation.\n• Not all Christians are satisfied by theodicies; many simply say suffering is a mystery but that God is present in it.\n\nContemporary examples: Christians often respond to disasters through relief agencies such as Tearfund, CAFOD or Christian Aid; hospital chaplains and the hospice movement (founded by Christian Dame Cicely Saunders) show compassion to those who suffer.\n\nKey terms: omnipotent, benevolent, just, agape, moral evil, natural evil, free will, theodicy, the Fall."},{"id":"aqa-rs-a-christianity-paper1-1-2","paper":"Beliefs","module":"1.2","title":"The nature of God: the oneness of God and the Trinity — Father, Son and Holy Spirit","specFocus":"Spec: Key beliefs — the nature of God: the oneness of God and the Trinity: Father, Son and Holy Spirit.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Christianity is a monotheistic religion: Christians believe in one God. Yet they also believe that God has revealed himself as three persons — Father, Son and Holy Spirit. This belief is called the Trinity (from 'tri-unity').\n\nThe oneness of God\n• Christianity inherited Jewish monotheism. The Shema says 'Hear, O Israel: the Lord our God, the Lord is one' (Deuteronomy 6:4); Jesus quoted it as the greatest commandment (Mark 12:29–30).\n• The first of the Ten Commandments forbids other gods (Exodus 20:3).\n• The Nicene Creed opens: 'We believe in one God'.\n\nThe Trinity\n• One God in three persons. Each person is fully God; they are distinct from one another; but there are not three gods.\n• The word 'Trinity' is not in the Bible, but Christians find the idea there: Jesus' baptism (Mark 1:9–11) — the Son is baptised, the Spirit descends like a dove, the Father speaks; the Great Commission — baptise 'in the name of the Father and of the Son and of the Holy Spirit' (Matthew 28:19); the Grace (2 Corinthians 13:14).\n• The doctrine was formally defined in the Nicene Creed (Councils of Nicaea 325 and Constantinople 381).\n\nThe three persons\n• God the Father: creator and sustainer of all; a loving parent ('Our Father in heaven', Matthew 6:9); 'the Father almighty' (Apostles' Creed).\n• God the Son: Jesus Christ, God incarnate, fully God and fully human; 'of one Being with the Father' (Nicene Creed); 'I and the Father are one' (John 10:30). He saves humanity through his death and resurrection.\n• God the Holy Spirit: God's presence and power in the world today; 'the Lord, the giver of life'; came upon the disciples at Pentecost (Acts 2); guides, comforts and strengthens ('the Advocate', John 14:26); produces the fruit of the Spirit (Galatians 5:22–23).\n\nDiversity of views\n• The filioque ('and the Son'): Catholic and most Protestant Churches say the Spirit proceeds 'from the Father and the Son'; Orthodox Christians say 'from the Father'. This was one cause of the Great Schism of 1054.\n• Pentecostal and charismatic churches emphasise the Spirit's gifts (tongues, healing, prophecy).\n• A few groups outside mainstream Christianity (e.g. Jehovah's Witnesses, Unitarians) reject the Trinity.\n• Analogies (shamrock, water/ice/steam, a person who is a parent, child and sibling) are popular but imperfect; the Church calls the Trinity a mystery.\n\nWhy it matters / influence\n• Worship: baptism in the threefold name; the sign of the cross; doxologies ('Glory be to the Father…'); creeds recited in services.\n• Prayer: often to the Father, through the Son, in the Spirit.\n• Relationships: the Trinity is a community of love, so Christians value community, unity and loving relationships.\n• Experience: Christians feel they know God as creator, as saviour in Jesus, and as an inner presence.\n\nKey terms: monotheism, Trinity, Father, Son, Holy Spirit, Nicene Creed, filioque, Pentecost, incarnation."},{"id":"aqa-rs-a-christianity-paper1-1-3","paper":"Beliefs","module":"1.3","title":"Different Christian beliefs about creation, including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3)","specFocus":"Spec: Key beliefs — different Christian beliefs about creation including the role of Word and Spirit (John 1:1–3 and Genesis 1:1–3). Both passages are prescribed texts and questions may be set on them.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Prescribed texts (learn them)\n• Genesis 1:1–3: 'In the beginning God created the heavens and the earth. Now the earth was formless and empty, darkness was over the surface of the deep, and the Spirit of God was hovering over the waters. And God said, \"Let there be light,\" and there was light.'\n• John 1:1–3: 'In the beginning was the Word, and the Word was with God, and the Word was God. He was with God in the beginning. Through him all things were made; without him nothing was made that has been made.'\n\nWhat they teach\n• God the Father is the creator; creation is ex nihilo (out of nothing) and purposeful.\n• The Spirit was present and active ('hovering'), bringing life and order — the Spirit is 'the giver of life' (Nicene Creed).\n• God creates by speaking ('And God said…'). John identifies this creative Word (Greek: Logos) with Jesus: 'The Word became flesh' (John 1:14). So the Son is eternal, not created, and all three persons of the Trinity were involved in creation.\n• Creation is good: 'God saw all that he had made, and it was very good' (Genesis 1:31).\n\nThe Genesis accounts\n• Genesis 1: six days — light; sky; land, seas and plants; sun, moon and stars; fish and birds; animals and humans — then God rests on the seventh day.\n• Genesis 2: God forms Adam from the dust and breathes life into him; plants the Garden of Eden; forms Eve from Adam's rib. Humans are given stewardship: 'to work it and take care of it' (Genesis 2:15).\n• Humans are made 'in the image of God' (imago Dei, Genesis 1:27).\n\nDifferent Christian beliefs about creation\n• Literalist / creationist: Genesis is literally true; six 24-hour days; a young Earth (some evangelical Protestants). Science must fit scripture.\n• Old Earth / 'day-age' view: each 'day' represents a long period of time.\n• Non-literal / theistic evolution: Genesis teaches spiritual truth (God is creator, the world is good, humans are special) not science. God worked through the Big Bang and evolution. This is the view of the Catholic Church, the Church of England and most mainstream churches. The Big Bang was first proposed by a Catholic priest, Georges Lemaître; Pope Francis (2014) said evolution is not inconsistent with creation.\n• Intelligent design: some argue life is too complex to have evolved without a designer.\n\nWhy it matters / influence\n• Stewardship: caring for the environment (e.g. A Rocha, Eco Church, Pope Francis's Laudato Si', 2015).\n• Sanctity and dignity of life: all humans in God's image deserve respect.\n• Worship: Christians praise God as creator (e.g. harvest festivals, psalms such as Psalm 8 and Psalm 19).\n• Jesus' divinity: John 1 supports belief that Jesus is God.\n\nKey terms: creation ex nihilo, Logos/Word, Spirit, imago Dei, stewardship, literalism, creationism, theistic evolution, Big Bang."},{"id":"aqa-rs-a-christianity-paper1-1-4","paper":"Beliefs","module":"1.4","title":"Different Christian beliefs about the afterlife and their importance: resurrection and life after death; judgement, heaven and hell","specFocus":"Spec: Key beliefs — different Christian beliefs about the afterlife and their importance, including: resurrection and life after death; judgement, heaven and hell.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Christians believe death is not the end. Their hope rests on the resurrection of Jesus.\n\nResurrection and life after death\n• Jesus rose from the dead on the third day; he is 'the firstfruits of those who have fallen asleep' (1 Corinthians 15:20) — a guarantee that believers will be raised too.\n• 'I am the resurrection and the life. The one who believes in me will live, even though they die' (John 11:25).\n• Resurrection of the body: the Apostles' Creed says 'I believe in… the resurrection of the body, and the life everlasting'. Paul says the raised body will be a transformed 'spiritual body', imperishable (1 Corinthians 15:42–44).\n• Timing differs: some believe the soul goes to God immediately at death (Jesus to the criminal: 'today you will be with me in paradise', Luke 23:43); others believe the dead 'sleep' until the general resurrection at the Second Coming (Parousia); many combine the two.\n\nJudgement\n• Christians believe God judges every person. Many believe in an individual judgement at death and a final Last Judgement when Christ returns.\n• Parable of the Sheep and the Goats (Matthew 25:31–46): people are judged on how they treated 'the least of these' — the hungry, thirsty, strangers, naked, sick and prisoners.\n• Some (especially many Protestants) stress that people are judged on faith in Christ and saved by grace; Catholics stress faith shown in works as well. Both agree on God's justice and mercy.\n\nHeaven\n• Eternal life with God, free from suffering: 'He will wipe every tear from their eyes' (Revelation 21:4); 'My Father's house has many rooms' (John 14:2).\n• Some see heaven as a physical place; others as a spiritual state of perfect union with God (the 'beatific vision').\n• Purgatory (Catholic): a state of purification for those who die in God's grace but are not yet fully holy; prayers for the dead help them. Most Protestants reject purgatory.\n\nHell\n• Traditionally eternal punishment and separation from God ('eternal punishment', Matthew 25:46).\n• Many now see hell as a state of separation chosen by people who freely reject God — 'definitive self-exclusion' (Catholic Catechism 1033).\n• Other views: annihilation (the unrepentant cease to exist); universalism (hope that all will finally be saved).\n• Challenge: how can a loving God allow eternal punishment? Responses stress God's justice and human free will.\n\nWhy these beliefs are important\n• They give meaning and purpose: life is a preparation for eternity.\n• Motivation to live morally and serve others, knowing actions matter.\n• Comfort and hope in bereavement — funeral services thank God for the person's life and commend them to God.\n• Belief in justice: wrongdoing will ultimately be dealt with, and the good rewarded.\n• Paul: 'if Christ has not been raised, your faith is futile' (1 Corinthians 15:17).\n\nKey terms: resurrection, eternal life, judgement, Parousia, heaven, hell, purgatory, annihilation, universalism."},{"id":"aqa-rs-a-christianity-paper1-1-5","paper":"Beliefs","module":"1.5","title":"Jesus Christ and salvation: the incarnation and Jesus as the Son of God","specFocus":"Spec: Jesus Christ and salvation — beliefs and teachings about the incarnation and Jesus as the Son of God.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"The incarnation\n• Incarnation means 'becoming flesh': God the Son took on a human nature and was born as Jesus of Nazareth.\n• 'The Word became flesh and made his dwelling among us' (John 1:14). The Word, who 'was God' (John 1:1), became a real human being.\n• Jesus is fully God and fully human — two natures in one person (Council of Chalcedon, 451). He was not half-and-half, nor God pretending to be human.\n\nThe birth narratives (Matthew 1–2 and Luke 1–2)\n• Jesus was conceived by the Holy Spirit and born of the Virgin Mary (the virgin birth / virginal conception).\n• The Annunciation: the angel Gabriel tells Mary, 'The Holy Spirit will come on you… the holy one to be born will be called the Son of God' (Luke 1:35).\n• Joseph is told the child will be called 'Immanuel — which means \"God with us\"' (Matthew 1:23).\n• Born in Bethlehem in humble circumstances, laid in a manger (Luke 2:7); visited by shepherds (Luke) and Magi (Matthew).\n\nEvidence of Jesus' humanity and divinity in the Gospels\n• Human: born, grew up, felt hunger, tiredness, temptation (Matthew 4), wept (John 11:35), suffered and died.\n• Divine: miracles; forgiving sins (Mark 2:5–7); transfiguration; resurrection; claims such as 'I and the Father are one' (John 10:30).\n\nJesus as the Son of God\n• At his baptism: 'You are my Son, whom I love; with you I am well pleased' (Mark 1:11).\n• 'Son of God' expresses a unique relationship with the Father and a shared divine nature — not a biological relationship.\n• The Nicene Creed: 'the only Son of God, eternally begotten of the Father… true God from true God, begotten, not made, of one Being with the Father'.\n• Other titles: Christ/Messiah ('anointed one'), Lord, Son of Man, Word (Logos), Immanuel.\n\nDiversity of views\n• Mainstream Catholic, Orthodox and Protestant churches all affirm the creeds.\n• Some liberal Christians interpret the virgin birth symbolically, while still believing God was uniquely present in Jesus; traditional Christians insist it is historical.\n• Catholics and Orthodox give Mary special honour as 'Mother of God' (Theotokos, Council of Ephesus 431) because of the incarnation; many Protestants honour her but place less emphasis on her.\n• Non-Christian views: Muslims see Jesus as a prophet; humanists as a moral teacher.\n\nImportance and influence\n• Shows God's love: God entered the world to save it (John 3:16).\n• Reveals God: 'Anyone who has seen me has seen the Father' (John 14:9).\n• God understands human weakness (Hebrews 4:15), encouraging prayer.\n• Jesus is a perfect example to follow; human life and the physical world are valuable.\n• Celebrated at Christmas; affirmed in creeds and hymns.\n\nKey terms: incarnation, virgin birth, Annunciation, Immanuel, Son of God, Messiah, Logos, Chalcedon, Theotokos."},{"id":"aqa-rs-a-christianity-paper1-1-6","paper":"Beliefs","module":"1.6","title":"Jesus Christ and salvation: the crucifixion, resurrection and ascension","specFocus":"Spec: Jesus Christ and salvation — beliefs and teachings about the crucifixion, resurrection and ascension.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"The crucifixion\n• After the Last Supper Jesus was arrested in Gethsemane, tried before the Jewish council and the Roman governor Pontius Pilate, and sentenced to death by crucifixion on Good Friday.\n• Key details: crucified between two criminals; sign 'The King of the Jews'; darkness at midday; the temple curtain torn in two (Mark 15:38); the centurion: 'Surely this man was the Son of God!' (Mark 15:39).\n• Words from the cross include: 'Father, forgive them, for they do not know what they are doing' (Luke 23:34); 'Today you will be with me in paradise' (Luke 23:43); 'My God, my God, why have you forsaken me?' (Mark 15:34, quoting Psalm 22); 'It is finished' (John 19:30).\n• Meaning: Jesus' death was a sacrifice for sin — 'a ransom for many' (Mark 10:45); 'Christ died for our sins' (1 Corinthians 15:3). It shows God's love (Romans 5:8), God sharing human suffering, and the power of forgiveness.\n\nThe resurrection\n• On the third day (Easter Sunday) women found the tomb empty: 'He has risen! He is not here' (Mark 16:6).\n• Appearances: Mary Magdalene (John 20), two disciples on the road to Emmaus (Luke 24), the disciples in the upper room, Thomas ('My Lord and my God!', John 20:28), over 500 people (1 Corinthians 15:6).\n• Jesus' risen body was real (he ate fish, Luke 24:42–43) but transformed (he appeared in locked rooms).\n• Meaning: proves Jesus is the Son of God; defeats sin and death; guarantees eternal life — 'the firstfruits' (1 Corinthians 15:20). 'If Christ has not been raised, your faith is futile' (1 Corinthians 15:17).\n• Diversity: most Christians believe in a bodily resurrection; some liberal Christians interpret it spiritually (the disciples experienced Jesus alive in a new way).\n\nThe ascension\n• Forty days after Easter, Jesus was 'taken up… and a cloud hid him from their sight' (Acts 1:9; also Luke 24:50–53).\n• Before leaving he promised the Holy Spirit and commissioned the disciples: 'you will be my witnesses… to the ends of the earth' (Acts 1:8).\n• Angels promised he would return in the same way (Acts 1:11) — the Second Coming (Parousia).\n• The creeds: 'he ascended into heaven and is seated at the right hand of the Father'.\n• Meaning: completes Jesus' earthly mission; Jesus reigns with the Father and intercedes for believers (Hebrews 7:25); makes way for Pentecost (John 16:7).\n\nImportance and influence today\n• Worship: Good Friday, Easter Sunday and Ascension Day; Sunday as the day of resurrection; the cross and crucifix as symbols; the Eucharist remembers Jesus' death.\n• Forgiveness: Christians are called to forgive as Jesus did.\n• Hope: the resurrection gives hope of eternal life and comfort at funerals.\n• Mission: the ascension commission inspires evangelism.\n\nKey terms: crucifixion, Good Friday, resurrection, empty tomb, ascension, Parousia/Second Coming, paschal mystery."},{"id":"aqa-rs-a-christianity-paper1-1-7","paper":"Beliefs","module":"1.7","title":"Jesus Christ and salvation: sin, including original sin","specFocus":"Spec: Jesus Christ and salvation — beliefs and teachings about sin, including original sin.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"What is sin?\n• Sin is any thought, word or action that goes against God's will and damages a person's relationship with God and others. The Greek word in the New Testament (hamartia) means 'missing the mark'.\n• Christians believe 'all have sinned and fall short of the glory of God' (Romans 3:23).\n• Jesus taught that sin begins in the heart: anger is like murder and lust like adultery (Matthew 5:21–28).\n• Examples of guidance: the Ten Commandments (Exodus 20), the Sermon on the Mount (Matthew 5–7).\n\nThe Fall (Genesis 3)\n• Adam and Eve lived in harmony with God in the Garden of Eden. God forbade them to eat from the tree of the knowledge of good and evil (Genesis 2:17).\n• The serpent tempted Eve; she and Adam ate the fruit. They felt shame, hid from God, and were expelled from Eden. Consequences: pain, toil, and death ('to dust you will return', Genesis 3:19).\n• The Fall shows humans misusing God's gift of free will.\n\nOriginal sin\n• The belief that the sin of Adam and Eve affected all humanity, so everyone is born with a tendency to sin and in a state of separation from God.\n• 'Sin entered the world through one man, and death through sin' (Romans 5:12); 'Surely I was sinful at birth' (Psalm 51:5).\n• Developed especially by St Augustine (4th–5th century).\n• Catholic teaching: original sin is 'contracted' not 'committed' — a state, not a personal act; it is removed in baptism, though its effects (concupiscence — the inclination to sin) remain (Catechism 405).\n• Orthodox Christians speak of 'ancestral sin': humans inherit mortality and a tendency to sin, but not Adam's guilt.\n• Some Protestant traditions (e.g. Calvinism) stress 'total depravity' — sin affects every part of human nature.\n• Some liberal Christians read Genesis 3 symbolically, as describing every human's experience rather than an event in history.\n\nThe remedy\n• Jesus is the 'new Adam': 'For as in Adam all die, so in Christ all will be made alive' (1 Corinthians 15:22).\n• God forgives those who repent: 'If we confess our sins, he is faithful and just and will forgive us' (1 John 1:9); the Parable of the Lost Son (Luke 15:11–32).\n\nInfluence today\n• Baptism: many churches baptise infants to cleanse original sin.\n• Confession: prayers of confession in services; the Catholic sacrament of Reconciliation.\n• Lord's Prayer: 'forgive us our trespasses… lead us not into temptation'.\n• Moral seriousness and humility; dependence on God's grace; forgiving others.\n• Lent is a season of repentance.\n\nChallenges\n• Fairness: why should people inherit the effects of someone else's sin? (Ezekiel 18:20.)\n• Humanists and some others argue humans are born neither good nor evil but shaped by environment.\n• Christians balance sin with the teaching that humans are made in God's image (Genesis 1:27) and that creation is 'very good'.\n\nKey terms: sin, the Fall, original sin, free will, concupiscence, repentance, confession, absolution, grace."},{"id":"aqa-rs-a-christianity-paper1-1-8","paper":"Beliefs","module":"1.8","title":"Jesus Christ and salvation: the means of salvation, including law, grace and Spirit","specFocus":"Spec: Jesus Christ and salvation — beliefs and teachings about the means of salvation, including law, grace and Spirit.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"What is salvation?\n• Salvation means being saved from sin and its consequences (separation from God, spiritual death) and brought into a restored relationship with God, leading to eternal life.\n• 'For God so loved the world that he gave his one and only Son, that whoever believes in him shall not perish but have eternal life' (John 3:16).\n• Christians differ about HOW people receive salvation. The specification names three means: law, grace and Spirit.\n\nSalvation through law (and good works)\n• God's law is given in the Old Testament, especially the Ten Commandments (Exodus 20). Jesus said he came 'not to abolish the Law… but to fulfil' it (Matthew 5:17).\n• Jesus summarised the law as loving God and loving your neighbour (Mark 12:30–31).\n• Some teachings link salvation to obedience: 'If you want to enter life, keep the commandments' (Matthew 19:17); 'faith by itself, if it is not accompanied by action, is dead' (James 2:17).\n• Catholic teaching: salvation is by God's grace, received through faith and the sacraments, and faith must be expressed in good works and keeping the commandments.\n• Problem: no one keeps the law perfectly (Romans 3:23).\n\nSalvation through grace\n• Grace is God's free, unearned love. 'It is by grace you have been saved, through faith — and this is not from yourselves, it is the gift of God — not by works, so that no one can boast' (Ephesians 2:8–9).\n• Martin Luther (Reformation, 1517 onwards) taught justification by faith alone (sola fide) and grace alone (sola gratia), from Romans 1:17. This is central for Protestants.\n• Good works are a response to grace, a sign of real faith, not a way of earning salvation.\n• The 1999 Joint Declaration on the Doctrine of Justification (Catholic Church and Lutheran World Federation) agreed that salvation is by grace through faith, and that good works follow.\n• Bonhoeffer warned against 'cheap grace' — grace without repentance or discipleship.\n\nSalvation through the Spirit\n• The Holy Spirit gives new life: 'no one can enter the kingdom of God unless they are born of water and the Spirit' (John 3:5) — being 'born again'.\n• The Spirit helps believers grow in holiness and produce the 'fruit of the Spirit' (Galatians 5:22–23), and assures them they are God's children (Romans 8:16).\n• Received at baptism and (for many) confirmation; Pentecostals emphasise a personal experience of the Spirit.\n• 'Repent and be baptised… you will receive the gift of the Holy Spirit' (Acts 2:38).\n\nBringing it together\n• Many Christians see salvation as the work of the Trinity: the Father's love (grace), the Son's sacrifice, and the Spirit's transforming power, with the law as the guide for living a saved life.\n• Orthodox Christians describe salvation as theosis — a lifelong journey of becoming more like God.\n\nInfluence\n• Gratitude and worship; humility; forgiving others; living by God's commandments; seeking the Spirit's help in prayer; taking part in sacraments; evangelism (sharing the good news of salvation).\n\nKey terms: salvation, law, grace, justification, faith, good works, sola fide, born again, Holy Spirit, theosis."},{"id":"aqa-rs-a-christianity-paper1-1-9","paper":"Beliefs","module":"1.9","title":"Jesus Christ and salvation: the role of Christ in salvation, including the idea of atonement","specFocus":"Spec: Jesus Christ and salvation — beliefs and teachings about the role of Christ in salvation including the idea of atonement.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Why salvation needs Christ\n• Christians believe sin separates humans from God, and that humans cannot repair this relationship on their own: 'the wages of sin is death, but the gift of God is eternal life in Christ Jesus our Lord' (Romans 6:23).\n• Jesus, fully God and fully human, is the one mediator who can bring God and humanity together.\n• 'I am the way and the truth and the life. No one comes to the Father except through me' (John 14:6); 'there is no other name under heaven… by which we must be saved' (Acts 4:12).\n\nAtonement\n• Atonement = 'at-one-ment': the restoring of the relationship between God and humanity through Jesus' life, death and resurrection.\n• 'We were reconciled to him through the death of his Son' (Romans 5:10).\n• 'Christ died for our sins according to the Scriptures' (1 Corinthians 15:3).\n\nDifferent understandings (models) of atonement\n• Sacrifice: Jesus is 'the Lamb of God, who takes away the sin of the world' (John 1:29), fulfilling the Temple sacrifices and Passover lamb. Hebrews describes him as the perfect high priest offering himself once for all.\n• Ransom: 'to give his life as a ransom for many' (Mark 10:45) — Jesus pays the price to free humanity from slavery to sin.\n• Substitution / satisfaction: Jesus takes the punishment humans deserve (Isaiah 53:5; 1 Peter 2:24). Anselm (Cur Deus Homo, c.1098) argued only a God-man could repay humanity's debt to God. Popular in evangelical Protestantism ('penal substitution').\n• Christus Victor: Jesus' death and resurrection defeat sin, death and the devil — 'Death has been swallowed up in victory' (1 Corinthians 15:54). Strong in Orthodox Christianity.\n• Moral example / influence: the cross reveals God's love and moves people to repent and love (Romans 5:8) — associated with Peter Abelard; emphasised by many liberal Christians.\n• Most Christians see these as complementary pictures rather than rival theories.\n\nThe resurrection and ascension in salvation\n• The resurrection shows the atonement has worked and that death is defeated (1 Corinthians 15:17, 20).\n• The risen and ascended Christ continues to 'intercede' for believers (Hebrews 7:25).\n\nDiversity of views on who is saved\n• Exclusivism: only those with explicit faith in Christ are saved (many evangelicals).\n• Inclusivism: salvation is through Christ, but may reach those who sincerely seek God without knowing him (Catholic Catechism 847).\n• Pluralism: many paths lead to God (a minority, liberal view).\n\nInfluence today\n• Holy Communion remembers Jesus' sacrifice: 'This is my body given for you' (Luke 22:19).\n• Good Friday and Easter; the cross as the central symbol.\n• Gratitude, assurance of forgiveness, and forgiving others.\n• Reconciliation work: 'he gave us the ministry of reconciliation' (2 Corinthians 5:18) — e.g. Coventry Cathedral's Community of the Cross of Nails, Corrymeela in Northern Ireland.\n• Evangelism: sharing the message of salvation (e.g. Alpha).\n\nKey terms: atonement, reconciliation, sacrifice, ransom, substitution, Christus Victor, redemption, Saviour, Lamb of God."},{"id":"aqa-rs-a-christianity-paper2-2-1","paper":"Practices","module":"2.1","title":"Worship: different forms of worship and their significance — liturgical, non-liturgical and informal, including the use of the Bible; private worship","specFocus":"Spec: Worship and festivals — different forms of worship and their significance: liturgical, non-liturgical and informal, including the use of the Bible; private worship.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Worship means showing love, reverence and praise to God. Christians worship together (public/corporate worship) and alone (private worship). The early Church 'devoted themselves to the apostles' teaching and to fellowship, to the breaking of bread and to prayer' (Acts 2:42). Jesus said true worshippers will worship 'in the Spirit and in truth' (John 4:23).\n\nLiturgical worship\n• A set order of service with set prayers, readings and actions, written down (e.g. Catholic Roman Missal; Anglican Book of Common Prayer / Common Worship; Orthodox Divine Liturgy).\n• Usually centred on Holy Communion, led by a priest. Often includes ritual, vestments, candles, incense and a church year with set readings (the lectionary).\n• Significance: links worshippers to tradition and to Christians worldwide; familiar words help everyone take part; balanced content (confession, Bible, creed, prayer, Eucharist). Catholic teaching calls the Eucharist 'the source and summit of the Christian life'.\n\nNon-liturgical worship\n• No fixed set of words; a structured service, but the minister chooses hymns, prayers and readings. Often centred on the Bible reading and sermon (e.g. many Baptist, Methodist, evangelical and URC churches).\n• Prayers may be extempore (made up in the moment).\n• Significance: flexible and relevant to local needs; strong emphasis on understanding and applying scripture.\n\nInformal worship\n• Spontaneous, with little or no set structure.\n• Pentecostal/charismatic: lively music, raised hands, spontaneous prayer, speaking in tongues, healing — inspired by Pentecost (Acts 2).\n• Quaker meetings: silent waiting on God; anyone may speak if moved by the Spirit; no clergy.\n• House churches, Messy Church, youth worship.\n• Significance: freedom for the Spirit to lead; personal and accessible; but critics say it can depend on emotion or the leader.\n\nUse of the Bible\n• Readings from the Old Testament, Psalms, Epistles and Gospel; the Gospel often honoured (standing, procession) in liturgical churches.\n• Sermons explain and apply passages; central in non-liturgical churches.\n• Prayers and songs draw on scripture (Lord's Prayer, psalms).\n• Personal and group study (house groups, daily Bible reading notes).\n• 'All Scripture is God-breathed and is useful for teaching' (2 Timothy 3:16).\n\nPrivate worship\n• Personal prayer, Bible reading, meditation, devotional practices.\n• Aids: the rosary (Catholic), icons (Orthodox), prayer apps, journals.\n• Jesus taught: 'go into your room, close the door and pray to your Father, who is unseen' (Matthew 6:6), and often prayed alone (Luke 5:16).\n• Significance: builds a personal relationship with God; can be done anywhere; supports daily discipleship.\n\nDiversity\n• Catholics have a duty to attend Mass on Sundays; Orthodox worship uses icons and chanting; Quakers reject set liturgy and sacraments; many Anglican churches offer both traditional and informal services.\n• Many Christians combine forms: Sunday liturgy, midweek house group and daily private prayer.\n\nContemporary examples: online/live-streamed services (widespread since 2020), Messy Church, Hillsong-style worship music, Taizé chants.\n\nKey terms: worship, liturgy, liturgical, non-liturgical, informal, sermon, extempore prayer, charismatic, private worship."},{"id":"aqa-rs-a-christianity-paper2-2-2","paper":"Practices","module":"2.2","title":"Prayer and its significance, including the Lord's Prayer, set prayers and informal prayer","specFocus":"Spec: Worship and festivals — prayer and its significance, including the Lord's Prayer, set prayers and informal prayer.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"What is prayer?\n• Prayer is communicating with God — speaking and listening. It can be spoken or silent, alone or with others.\n• Purposes are often remembered by ACTS: Adoration (praise), Confession (saying sorry), Thanksgiving, Supplication (asking — for oneself, petition; for others, intercession).\n• 'Pray continually; give thanks in all circumstances' (1 Thessalonians 5:17–18).\n• Jesus' teaching: pray sincerely and privately (Matthew 6:5–6); don't 'babble' with many words (Matthew 6:7); 'Ask and it will be given to you' (Matthew 7:7).\n• Jesus' example: praying alone (Luke 5:16); in Gethsemane, 'not as I will, but as you will' (Matthew 26:39).\n\nThe Lord's Prayer (Matthew 6:9–13; Luke 11:2–4)\nOur Father in heaven, hallowed be your name, your kingdom come, your will be done, on earth as in heaven. Give us today our daily bread. Forgive us our sins as we forgive those who sin against us. Lead us not into temptation but deliver us from evil. [For the kingdom, the power and the glory are yours, now and for ever. Amen.]\n• Significance: taught by Jesus himself as a model ('This, then, is how you should pray'); used by all denominations — a sign of unity; a summary of faith: praise, God's will first, daily needs, forgiveness, protection.\n• 'Our Father' shows a personal, loving relationship and that Christians are one family.\n• Influence: forgiving others; working for God's kingdom of justice on earth; trusting God for daily needs.\n• The closing doxology is used by Protestants and in some modern liturgies; Catholics say it separately at Mass.\n\nSet (formal) prayers\n• Prayers with fixed words, used repeatedly: the Lord's Prayer, the Hail Mary, the Jesus Prayer ('Lord Jesus Christ, Son of God, have mercy on me, a sinner' — Orthodox), the Grace, collects in the Book of Common Prayer, the Glory Be.\n• Aids: rosary beads (Catholic), prayer ropes (Orthodox).\n• Significance: help when people can't find words; unite congregations; ensure prayer is rooted in tradition and scripture; can be meditative.\n• Criticism: may become automatic or meaningless if said without thought.\n\nInformal (extempore) prayer\n• Prayers in one's own words, spontaneous, often personal — common in evangelical, Methodist, Baptist, Pentecostal churches and in private prayer.\n• Pentecostals may pray in tongues; Quakers pray in silence.\n• Significance: personal relationship with God; addresses specific needs; openness to the Holy Spirit, who 'helps us in our weakness' (Romans 8:26).\n• Criticism: can become self-centred or depend on the person's confidence.\n\nDiversity and contemporary examples\n• Catholics may pray to Mary and the saints to intercede for them; most Protestants pray directly to God only.\n• Prayer chains, prayer apps, 24-7 Prayer movement (begun in the UK in 1999), Taizé chant, Thy Kingdom Come (an annual global prayer movement between Ascension and Pentecost).\n\nUnanswered prayer\n• Christians believe God always hears prayer but may answer 'no' or 'not yet', or answer in an unexpected way — as Jesus accepted in Gethsemane.\n\nKey terms: prayer, adoration, confession, thanksgiving, supplication, intercession, set prayer, informal/extempore prayer, Lord's Prayer, rosary."},{"id":"aqa-rs-a-christianity-paper2-2-3","paper":"Practices","module":"2.3","title":"The role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism — infant and believers' baptism","specFocus":"Spec: Worship and festivals — the role and meaning of the sacraments: the meaning of sacrament; the sacrament of baptism and its significance for Christians; infant and believers' baptism; different beliefs about infant baptism.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"The meaning of sacrament\n• A sacrament is 'an outward and visible sign of an inward and spiritual grace' (Book of Common Prayer catechism, following St Augustine). Through physical things — water, bread, wine, oil — Christians believe they receive God's grace.\n• Catholic and Orthodox Churches: seven sacraments — baptism, confirmation (Orthodox: chrismation), Eucharist, reconciliation, anointing of the sick, marriage, holy orders. They are 'necessary for salvation' for believers (Catechism 1129).\n• Most Protestants (e.g. Anglicans, Methodists, Baptists): two sacraments commanded by Jesus — baptism (Matthew 28:19) and Holy Communion (Luke 22:19). Anglicans regard the other five as sacramental rites.\n• Quakers and the Salvation Army celebrate no outward sacraments; they believe grace is received inwardly and all of life is sacramental.\n\nBaptism — significance\n• Commanded by Jesus: 'go and make disciples of all nations, baptising them in the name of the Father and of the Son and of the Holy Spirit' (Matthew 28:19).\n• Jesus' own baptism by John in the River Jordan (Mark 1:9–11).\n• Meaning: cleansing from sin (including original sin); dying and rising with Christ — 'buried with him through baptism… we too may live a new life' (Romans 6:4); receiving the Holy Spirit; becoming a member of the Church, God's family.\n• Rite of initiation; for most churches it happens only once.\n\nInfant baptism (Catholic, Orthodox, Anglican, Methodist, URC…)\n• Usually at a font; water poured on the baby's head three times with the Trinitarian formula; sign of the cross; anointing with chrism oil (Catholic/Orthodox); white garment; lighted candle (Christ the light of the world).\n• Parents and godparents promise to bring the child up in the faith and reject evil; the congregation promises support.\n• Orthodox babies are fully immersed three times and receive chrismation and communion straight away.\n• Reasons: removes original sin; grace is God's gift, not dependent on understanding; household baptisms (Acts 16:33); 'the promise is for you and your children' (Acts 2:39); welcomes the child into the Church; later confirmed by the person at confirmation.\n\nBelievers' baptism (Baptist, many Pentecostal and evangelical churches)\n• Only for those old enough to choose — teenagers or adults who have repented and believe.\n• Usually by full immersion in a baptistery pool, river or sea; the candidate gives a testimony of faith and is asked if they will follow Jesus.\n• Reasons: New Testament pattern of faith then baptism — 'Repent and be baptised' (Acts 2:38); the Ethiopian official (Acts 8:36–38); Jesus was baptised as an adult; immersion best shows burial and resurrection (Romans 6:4); baptism should be a free personal commitment.\n• Babies may instead have a dedication or thanksgiving service.\n\nDifferent beliefs about infant baptism\n• For: grace, original sin, family faith, Church tradition since early centuries.\n• Against: babies cannot have faith; risk of nominal Christianity; no explicit New Testament example of baby baptism.\n\nContemporary context: numbers of infant baptisms in the Church of England have fallen significantly in recent decades, while believers' baptisms are prominent in growing evangelical and Pentecostal churches, sometimes held outdoors at beaches or rivers.\n\nKey terms: sacrament, grace, baptism, font, baptistery, immersion, godparents, infant baptism, believers' baptism, confirmation, dedication."},{"id":"aqa-rs-a-christianity-paper2-2-4","paper":"Practices","module":"2.4","title":"The sacrament of Holy Communion/Eucharist: its significance, different ways it is celebrated and different interpretations of its meaning","specFocus":"Spec: Worship and festivals — the sacrament of Holy Communion/Eucharist and its significance for Christians, including different ways in which it is celebrated and different interpretations of its meaning.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Origin\n• Holy Communion remembers the Last Supper, Jesus' Passover meal with his disciples the night before he died. 'He took bread, gave thanks and broke it, and gave it to them, saying, \"This is my body given for you; do this in remembrance of me.\" In the same way… he took the cup, saying, \"This cup is the new covenant in my blood\"' (Luke 22:19–20; 1 Corinthians 11:23–26).\n• The early Church 'devoted themselves… to the breaking of bread' (Acts 2:42).\n\nNames\n• Eucharist ('thanksgiving'), Mass (Catholic), Divine Liturgy (Orthodox service), Lord's Supper, Breaking of Bread, Holy Communion.\n\nSignificance\n• Obeying Jesus' command; remembering his sacrifice and resurrection.\n• Receiving God's grace and spiritual nourishment — 'I am the bread of life' (John 6:35).\n• Unity: 'Because there is one loaf, we, who are many, are one body' (1 Corinthians 10:17).\n• Proclaiming 'the Lord's death until he comes' (1 Corinthians 11:26).\n• Catholic: 'the source and summit of the Christian life' (Catechism 1324).\n\nDifferent ways it is celebrated\n• Catholic Mass: daily and weekly (Sunday obligation); Liturgy of the Word then Liturgy of the Eucharist; priest consecrates unleavened hosts and wine at the altar; people receive the host (on the tongue or hand) and sometimes the cup; leftover hosts are reserved in the tabernacle.\n• Orthodox Divine Liturgy: much takes place behind the iconostasis; leavened bread mixed with wine is given on a spoon; infants receive Communion after baptism and chrismation.\n• Anglican (Church of England): usually weekly; Common Worship liturgy; bread/wafers and a shared chalice; kneeling at an altar rail is common.\n• Nonconformist (e.g. Baptist, Methodist, URC): often monthly or less; ordinary bread and often non-alcoholic wine; may be passed around the seated congregation in small individual cups; simpler service focused on the words of institution.\n• Quakers and the Salvation Army: do not celebrate it outwardly.\n\nDifferent interpretations of its meaning\n• Transubstantiation (Catholic): the substance of bread and wine becomes the body and blood of Christ at consecration; the appearances remain (Council of Trent; Catechism 1376). Based on 'This is my body' and John 6:53–55.\n• Orthodox: a real change, understood as a holy mystery without the philosophical definition.\n• Lutheran (often called 'consubstantiation', though Lutherans themselves prefer 'sacramental union'): Christ is truly present 'in, with and under' the bread and wine.\n• Anglican: a range — many speak of the real presence; others a spiritual presence.\n• Memorialism (Zwingli; many Baptists): bread and wine are symbols that help believers remember Christ's sacrifice; 'do this in remembrance of me'.\n\nWho may receive?\n• Catholics generally ask only Catholics in a state of grace to receive; many Protestant churches practise 'open table', inviting all baptised Christians (or all who love Jesus).\n• This is a source of division among churches, and a focus for ecumenical dialogue.\n\nContemporary issues: during the COVID-19 pandemic many churches suspended the shared cup; some offered 'spiritual communion' online; gluten-free hosts and non-alcoholic options are now widely provided.\n\nKey terms: Eucharist, Mass, Lord's Supper, consecration, host, chalice, transubstantiation, real presence, memorial, open table."}],"rubrics":{"Beliefs":{"1":"1 mark (AO1). Two kinds of 1-mark item: (a) multiple choice — choose the one correct answer from A–D; (b) short response ('Give one…' / 'Name…') — one accurate, relevant point earns the mark; extra points are not needed and do not add marks.","12":"Evaluate (12 marks, AO2: analyse and evaluate aspects of religion and belief, including significance and influence). Levels of response, best fit. Level 4 (10–12): a well-argued response with reasoned consideration of different points of view; logical chains of reasoning leading to judgement(s) supported by accurate knowledge; religious teaching applied to the issue. Level 3 (7–9): reasoned consideration of different points of view; logical chains of reasoning drawing on relevant knowledge; clear reference to religion. Level 2 (4–6): reasoned consideration of one point of view, OR recognition of different points of view each supported by relevant reasons; maximum Level 2 if there is no reference to religion. Level 1 (1–3): a point of view with reason(s) stated in support. 0: nothing worthy of credit. Answers must follow the four bullets: refer to Christian teaching, argue for the statement, argue for a different view, and reach a justified conclusion. Up to 3 extra marks for spelling, punctuation and grammar (SPaG) are awarded on the 12-mark question in the Beliefs section: High 3 (consistent accuracy, wide range of specialist terms), Intermediate 2, Threshold 1.","4":"Explain two ways (4 marks, AO1). For each of two ways: a simple explanation of a relevant, accurate point = 1 mark; a detailed (developed) explanation = 2 marks. In the Beliefs section these items usually ask how a belief influences Christians today (AO1:2 influence on individuals, communities and societies).","6":"Explain two… and refer to sacred writings or another source of Christian belief and teaching (6 marks, AO1). First point: simple explanation 1 mark, detailed explanation 2 marks. Second point: simple 1, detailed 2. Source of authority: 2 marks for naming AND applying a relevant source (e.g. a Bible passage, creed, catechism or church teaching) to the question; 1 mark for only naming it or only applying it. Up to 6 marks in total. (From June 2026 this replaced the former 5-mark item; the question stem is unchanged.)"},"Practices":{"1":"1 mark (AO1). Two kinds of 1-mark item: (a) multiple choice — choose the one correct answer from A–D; (b) short response ('Give one…' / 'Name…') — one accurate, relevant point earns the mark; extra points are not needed and do not add marks.","12":"Evaluate (12 marks, AO2: analyse and evaluate aspects of religion and belief, including significance and influence). Levels of response, best fit. Level 4 (10–12): a well-argued response with reasoned consideration of different points of view; logical chains of reasoning leading to judgement(s) supported by accurate knowledge; religious teaching applied to the issue. Level 3 (7–9): reasoned consideration of different points of view; logical chains of reasoning drawing on relevant knowledge; clear reference to religion. Level 2 (4–6): reasoned consideration of one point of view, OR recognition of different points of view each supported by relevant reasons; maximum Level 2 if there is no reference to religion. Level 1 (1–3): a point of view with reason(s) stated in support. 0: nothing worthy of credit. Answers must follow the four bullets: refer to Christian teaching, argue for the statement, argue for a different view, and reach a justified conclusion. SPaG is not assessed on the Practices 12-mark question (it is assessed on the Beliefs 12-mark question).","4":"Explain two ways (4 marks, AO1). For each of two ways: a simple explanation of a relevant, accurate point = 1 mark; a detailed (developed) explanation = 2 marks. In the Practices section these items often ask for two different ways a practice is carried out or understood within Christianity (AO1:3 similarities and differences), or for two ways a practice influences Christians.","6":"Explain two… and refer to sacred writings or another source of Christian belief and teaching (6 marks, AO1). First point: simple explanation 1 mark, detailed explanation 2 marks. Second point: simple 1, detailed 2. Source of authority: 2 marks for naming AND applying a relevant source (e.g. a Bible passage, creed, catechism or church teaching) to the question; 1 mark for only naming it or only applying it. Up to 6 marks in total. (From June 2026 this replaced the former 5-mark item; the question stem is unchanged.)"}},"moduleCounts":{"paper1":9,"paper2":4},"meta":{"modulesTotal":13,"paper1QuestionCount":90,"paper2QuestionCount":40,"provenance":"Original practice questions written to the AQA GCSE Religious Studies A (8062) specification (section 3.1.2 Christianity: beliefs and teachings; practices) and its published question structure for exams from June 2026. Not past-paper material: no questions are copied from AQA past papers, sample papers, mark schemes, textbooks or revision guides. Model answers and notes are indicative exemplars written for this app, not official AQA mark schemes. Short Bible quotations are cited in each question's evidence list.","qualification":"AQA GCSE Religious Studies A (8062), Component 1: The study of religions — Christianity (paper 8062/11)","questionTotal":130,"title":"AQA GCSE Religious Studies A — Christianity"}});
